import { memo } from 'react';
import { useTilt } from '@/hooks/use-tilt';

/**
 * 烫金文字（B2 Foil Shimmer）
 * 金箔底 + 随陀螺仪偏移的高光层，模拟真实请柬烫金随角度变色的质感
 * 无陀螺仪时高光缓慢流光（useTilt 内置 fallback）
 */

interface FoilTextProps {
  children: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
  /** 高光带宽度百分比，默认 200（越大光带越窄） */
  size?: number;
}

function FoilText({ children, className = '', style, size = 200 }: FoilTextProps) {
  const tilt = useTilt();

  const foilBase: React.CSSProperties = {
    backgroundImage:
      'linear-gradient(135deg, #B8973F 0%, #D4AF37 20%, #F4E4BC 40%, #E8D193 55%, #C9A961 75%, #B8973F 100%)',
    WebkitBackgroundClip: 'text',
    backgroundClip: 'text',
    WebkitTextFillColor: 'transparent',
  };

  // 高光层：窄白光带，background-position 随倾斜移动
  const highlight: React.CSSProperties = {
    backgroundImage:
      'linear-gradient(100deg, transparent 42%, rgba(255,252,240,0.9) 50%, transparent 58%)',
    backgroundSize: `${size}% 100%`,
    backgroundPosition: `${50 + tilt * 45}% 0%`,
    WebkitBackgroundClip: 'text',
    backgroundClip: 'text',
    WebkitTextFillColor: 'transparent',
    pointerEvents: 'none',
  };

  return (
    <span className={`relative inline-block ${className}`} style={style}>
      <span style={foilBase}>{children}</span>
      <span aria-hidden="true" style={highlight} className="absolute inset-0">
        {children}
      </span>
    </span>
  );
}

export default memo(FoilText);
