import { memo, useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import SectionWrapper from '@/components/SectionWrapper';
import FloralHeartDecor from '@/components/FloralHeartDecor';
import FoilText from '@/components/FoilText';
import { useCountdown } from '@/hooks/use-countdown';
import { WEDDING_DATE } from '@/lib/constants';
import { MOCK_WEDDING_INFO } from '@/data/wedding';

function CountdownSection() {
  const { days, hours, minutes, seconds, isPast } = useCountdown(WEDDING_DATE);

  if (isPast) {
    return (
      <SectionWrapper id="countdown" className="bg-gradient-to-b from-background via-secondary/20 to-background">
        <div className="text-center">
          <motion.p
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.8 }}
            className="text-lg font-medium text-primary md:text-xl"
            style={{ fontFamily: "'Playfair Display', 'Noto Serif SC', serif" }}
          >
            我们的婚礼已圆满礼成
          </motion.p>
          <motion.p
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.8, delay: 0.2 }}
            className="mt-3 text-sm text-muted-foreground"
          >
            感谢您的见证与祝福，愿美好常驻心间
          </motion.p>
        </div>
      </SectionWrapper>
    );
  }

  const items = [
    { value: days, label: '天' },
    { value: hours, label: '时' },
    { value: minutes, label: '分' },
    { value: seconds, label: '秒', pulse: true },
  ];

  return (
    <SectionWrapper id="countdown" className="bg-gradient-to-b from-background via-secondary/20 to-background">
      <div className="relative text-center">
        {/* 鲜花爱心装饰 */}
        <FloralHeartDecor className="absolute -left-4 -top-6 z-0 h-20 w-20 opacity-60" variant="topLeft" />
        <FloralHeartDecor className="absolute -right-4 -top-6 z-0 h-20 w-20 opacity-60" variant="topRight" />
        <p className="text-xs tracking-[0.3em] text-muted-foreground">COUNTDOWN</p>
        <h2
          className="mt-2 text-2xl font-light tracking-wider md:text-3xl"
          style={{ fontFamily: "'Playfair Display', 'Noto Serif SC', serif" }}
        >
          <FoilText>距离婚礼还有</FoilText>
        </h2>
        <p className="mt-1 text-sm text-muted-foreground">{MOCK_WEDDING_INFO.weddingDate} · {MOCK_WEDDING_INFO.weddingTime}</p>

        <div className="mt-8 grid grid-cols-4 gap-2 md:gap-4">
          {items.map((item, idx) => (
            <FlipNumber key={item.label} value={item.value} label={item.label} delay={idx * 0.1} pulse={item.pulse} />
          ))}
        </div>
      </div>

      {/* 倒计时数字流光动画 */}
      <style>{`
        @keyframes goldShimmerSlide {
          0% { background-position: 0% 0; }
          100% { background-position: -200% 0; }
        }
        .gold-shimmer {
          animation: goldShimmerSlide 4s linear infinite;
        }
        @media (prefers-reduced-motion: reduce) {
          .gold-shimmer { animation: none; }
        }
      `}</style>
    </SectionWrapper>
  );
}

interface FlipNumberProps {
  value: number;
  label: string;
  delay: number;
  pulse?: boolean;
}

function FlipNumber({ value, label, delay, pulse }: FlipNumberProps) {
  const [displayValue, setDisplayValue] = useState(value);
  const [isFlipping, setIsFlipping] = useState(false);

  useEffect(() => {
    if (value !== displayValue) {
      setIsFlipping(true);
      const t = setTimeout(() => {
        setDisplayValue(value);
        setIsFlipping(false);
      }, 300);
      return () => clearTimeout(t);
    }
  }, [value, displayValue]);

  const padded = String(displayValue).padStart(2, '0');

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.6, delay }}
      className="flex flex-col items-center"
    >
      <div
        className="relative flex h-16 w-full items-center justify-center overflow-visible rounded-lg md:h-20"
        style={{
          background: 'rgba(255,255,255,0.5)',
          backdropFilter: 'blur(8px)',
          border: '1px solid rgba(212,175,55,0.25)',
          boxShadow: '0 4px 16px rgba(212,175,55,0.08)',
        }}
      >
        <AnimatePresence mode="wait">
          <motion.span
            key={padded}
            initial={{ rotateX: -90, opacity: 0 }}
            animate={{
              rotateX: 0,
              opacity: 1,
              scale: pulse && isFlipping ? [1, 1.12, 1] : 1,
            }}
            exit={{ rotateX: 90, opacity: 0 }}
            transition={{ duration: 0.3, ease: 'easeInOut' }}
            className="gold-shimmer font-serif text-3xl font-semibold md:text-4xl"
            style={{
              fontFamily: "'Playfair Display', serif",
              backgroundImage: 'linear-gradient(110deg, #C9A961 0%, #D4AF37 30%, #F4E4BC 50%, #D4AF37 70%, #C9A961 100%)',
              backgroundSize: '200% 100%',
              WebkitBackgroundClip: 'text',
              backgroundClip: 'text',
              WebkitTextFillColor: 'transparent',
            }}
          >
            {padded}
          </motion.span>
        </AnimatePresence>
        {/* 中缝装饰线 */}
        <div className="pointer-events-none absolute left-0 right-0 top-1/2 h-px -translate-y-1/2 bg-foreground/5" />

        {/* 秒数心跳：心形扩散 */}
        {pulse && isFlipping && (
          <>
            {/* 第一层心形扩散 */}
            <motion.div
              initial={{ opacity: 0.5, scale: 0.3 }}
              animate={{ opacity: 0, scale: 2.5 }}
              transition={{ duration: 0.6, ease: 'easeOut' }}
              className="pointer-events-none absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2"
              style={{ zIndex: 20 }}
            >
              <svg width="40" height="40" viewBox="0 0 24 24" fill="rgba(212,165,165,0.6)">
                <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
              </svg>
            </motion.div>
            {/* 第二层金色光环扩散 */}
            <motion.div
              initial={{ opacity: 0.3, scale: 0.5 }}
              animate={{ opacity: 0, scale: 1.8 }}
              transition={{ duration: 0.5, ease: 'easeOut', delay: 0.05 }}
              className="pointer-events-none absolute inset-0 rounded-lg"
              style={{ border: '2px solid rgba(212,175,55,0.4)' }}
            />
          </>
        )}
      </div>
      <span className="mt-2 text-xs text-muted-foreground">{label}</span>
    </motion.div>
  );
}

export default memo(CountdownSection);
