import { useEffect, useRef, memo } from 'react';

/**
 * 贯穿全页的金线叙事（B1）
 * 一条香槟金丝线从封面新人名字处垂下，随滚动蜿蜒生长，
 * 途经各板块左右摆动，末端收成心结。滚动回退时金线回缩。
 *
 * 实现：绝对定位 SVG 铺满整个文档高度，贝塞尔蛇形路径，
 * scroll 进度驱动 stroke-dashoffset（直接操作 DOM，无 React 重渲染）。
 * 尊重 prefers-reduced-motion：直接完整显示。
 */

function GoldenThread() {
  const svgRef = useRef<SVGSVGElement>(null);
  const pathRef = useRef<SVGPathElement>(null);
  const lenRef = useRef(0);

  useEffect(() => {
    const svg = svgRef.current;
    const path = pathRef.current;
    if (!svg || !path) return;

    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    /** 构建蛇形路径：从 hero 名字高度到文档底部，末端带一颗心 */
    const build = () => {
      const w = window.innerWidth;
      const h = Math.max(
        document.documentElement.scrollHeight,
        document.body.scrollHeight
      );
      const top = Math.min(window.innerHeight * 0.42, 420);
      const bottom = h - 40;

      svg.setAttribute('viewBox', `0 0 ${w} ${h}`);
      svg.setAttribute('width', String(w));
      svg.setAttribute('height', String(h));

      const cx = w * 0.5;
      const amp = w * 0.3; // 左右摆幅
      const segs = 11;
      const segH = (bottom - top - 120) / segs;

      let d = `M ${cx} ${top}`;
      for (let i = 0; i < segs; i++) {
        const y0 = top + segH * i;
        const y1 = y0 + segH;
        const dir = i % 2 === 0 ? 1 : -1;
        const px = cx + dir * amp * (0.55 + ((i * 7) % 3) * 0.12);
        d += ` C ${px} ${y0 + segH * 0.35}, ${px} ${y1 - segH * 0.35}, ${cx} ${y1}`;
      }

      // 末端心结：线收进一颗小心形
      const hx = cx;
      const hy = top + segH * segs + 26;
      const s = 20; // 心形缩放
      d +=
        ` C ${hx} ${hy - 30}, ${hx - s * 1.4} ${hy - s}, ${hx - s} ${hy + s * 0.4}` +
        ` C ${hx - s * 0.6} ${hy + s * 1.2}, ${hx} ${hy + s * 1.6}, ${hx} ${hy + s * 2}` +
        ` C ${hx} ${hy + s * 1.6}, ${hx + s * 0.6} ${hy + s * 1.2}, ${hx + s} ${hy + s * 0.4}` +
        ` C ${hx + s * 1.4} ${hy - s}, ${hx} ${hy - 30}, ${hx} ${hy - s * 2.6}`;

      path.setAttribute('d', d);
      lenRef.current = path.getTotalLength();
      path.setAttribute('stroke-dasharray', String(lenRef.current));

      if (reduced) {
        path.setAttribute('stroke-dashoffset', '0');
      } else {
        update();
      }
    };

    /** 滚动进度 → dashoffset */
    let raf = 0;
    const update = () => {
      raf = 0;
      const docH = document.documentElement.scrollHeight - window.innerHeight;
      const progress = docH > 0 ? Math.min(1, Math.max(0, window.scrollY / docH)) : 0;
      if (pathRef.current && lenRef.current > 0) {
        // 比滚动进度略快一点，让线始终"领着"视线
        const p = Math.min(1, progress * 1.15 + 0.03);
        pathRef.current.setAttribute('stroke-dashoffset', String(lenRef.current * (1 - p)));
      }
    };

    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(update);
    };

    build();
    if (!reduced) {
      window.addEventListener('scroll', onScroll, { passive: true });
    }
    const resizeTimer = window.setInterval(build, 3000); // 图片加载会撑高文档，定期重算
    window.addEventListener('resize', build);

    return () => {
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', build);
      window.clearInterval(resizeTimer);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);

  return (
    <svg
      ref={svgRef}
      aria-hidden="true"
      className="pointer-events-none absolute inset-0 z-[5]"
      style={{ opacity: 0.5 }}
    >
      <defs>
        <linearGradient id="thread-gold" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#D4AF37" stopOpacity="0.9" />
          <stop offset="50%" stopColor="#F4E4BC" stopOpacity="0.75" />
          <stop offset="100%" stopColor="#C9A961" stopOpacity="0.85" />
        </linearGradient>
      </defs>
      <path
        ref={pathRef}
        d=""
        fill="none"
        stroke="url(#thread-gold)"
        strokeWidth="1.4"
        strokeLinecap="round"
        style={{ filter: 'drop-shadow(0 0 3px rgba(212,175,55,0.35))' }}
      />
    </svg>
  );
}

export default memo(GoldenThread);
