/**
 * 地图导航跳转工具
 * - 高德地图（推荐）：marker + navigation 模式，传入坐标精准定位
 * - 百度地图：marker 模式 + 兜底地址搜索
 * - 腾讯地图：uri/v1/marker 模式
 * - 系统地图：高德降级（国内用户）
 *
 * 微信内浏览器：使用 location.href 唤起，避免 window.open 被拦截
 * 原生 App 唤起：先尝试 scheme，失败回退到 H5 页面
 */

export interface NavOptions {
  address: string;
  lat?: number;
  lng?: number;
  name?: string;
}

/**
 * 检测是否在微信内浏览器
 */
function isWeChat(): boolean {
  if (typeof navigator === 'undefined') return false;
  return /micromessenger/i.test(navigator.userAgent);
}

/**
 * 检测是否在原生 App WebView（不支持外部跳转）
 */
function isInApp(): boolean {
  if (typeof navigator === 'undefined') return false;
  const ua = navigator.userAgent.toLowerCase();
  return /micromessenger|qq\/|weibo|dingtalk/i.test(ua);
}

/**
 * 唤起原生地图 App + 兜底 H5 页面
 */
function launchNative(scheme: string, fallback: string): void {
  // 1. 创建隐藏 iframe 唤起 scheme
  const iframe = document.createElement('iframe');
  iframe.style.display = 'none';
  iframe.src = scheme;
  document.body.appendChild(iframe);

  // 2. 500ms 后移除 iframe，并跳转到兜底页面
  setTimeout(() => {
    document.body.removeChild(iframe);
    // 仅当用户未离开页面时才跳转兜底
    if (document.visibilityState === 'visible') {
      window.location.href = fallback;
    }
  }, 500);
}

/**
 * 直接跳转 H5 页面（兼容微信内浏览器）
 */
function openH5(url: string): void {
  if (isInApp()) {
    // 微信/QQ/微博内：直接 location.href（避免被拦截）
    window.location.href = url;
  } else {
    // 普通浏览器：直接 location.href 也更可靠
    window.location.href = url;
  }
}

/**
 * 打开高德地图导航
 * - 有坐标：直接定位 marker + 唤起原生 App
 * - 无坐标：地址搜索
 */
export function openAmapNav(options: NavOptions): void {
  const { address, lat, lng, name = '婚礼现场' } = options;

  if (lat && lng) {
    // 1. 高德 H5 URL（marker 模式直接定位）
    const webUrl = `https://uri.amap.com/marker?markers=${lng},${lat},${encodeURIComponent(name)}&src=wedding&callnative=1`;
    // 2. 高德原生 scheme（直接打开 App）
    const scheme = `androidamap://viewMap?sourceApplication=wedding&poiname=${encodeURIComponent(name)}&lat=${lat}&lon=${lng}&dev=0`;
    launchNative(scheme, webUrl);
  } else {
    // 无坐标：地址搜索
    const webUrl = `https://uri.amap.com/search?keyword=${encodeURIComponent(address)}&src=wedding&callnative=1`;
    openH5(webUrl);
  }
}

/**
 * 打开高德地图直接进入导航模式
 */
export function openAmapNavigation(options: NavOptions): void {
  const { lat, lng, name = '婚礼现场' } = options;
  if (!lat || !lng) {
    openAmapNav(options);
    return;
  }
  const webUrl = `https://uri.amap.com/navigation?to=${lng},${lat},${encodeURIComponent(name)}&mode=car&policy=1&src=wedding&callnative=1&coordinate=gaode`;
  const scheme = `androidamap://navi?sourceApplication=wedding&lat=${lat}&lon=${lng}&dev=0&style=2`;
  launchNative(scheme, webUrl);
}

/**
 * 打开百度地图导航
 * 注意：百度坐标系是 BD09，这里传入 GCJ02 坐标会自动转换
 */
export function openBmapNav(options: NavOptions): void {
  const { address, lat, lng, name = '婚礼现场' } = options;

  if (lat && lng) {
    // 百度 H5 marker 模式（传入 GCJ02 坐标，自动转换为 BD09）
    const webUrl = `https://api.map.baidu.com/marker?location=${lat},${lng}&title=${encodeURIComponent(name)}&content=${encodeURIComponent(address)}&output=html&coordtype=gcj02&src=wedding`;
    // 百度原生 scheme
    const scheme = `baidumap://map/marker?location=${lat},${lng}&title=${encodeURIComponent(name)}&src=wedding&content=${encodeURIComponent(address)}`;
    launchNative(scheme, webUrl);
  } else {
    // 无坐标：地址搜索
    const webUrl = `https://api.map.baidu.com/geocoder?address=${encodeURIComponent(address)}&output=html&src=wedding`;
    openH5(webUrl);
  }
}

/**
 * 打开腾讯地图导航
 */
export function openTencentMapNav(options: NavOptions): void {
  const { address, lat, lng, name = '婚礼现场' } = options;

  if (lat && lng) {
    // 腾讯 H5 marker 模式
    const webUrl = `https://apis.map.qq.com/uri/v1/marker?marker=coord:${lat},${lng};title:${encodeURIComponent(name)};addr:${encodeURIComponent(address)}&referer=wedding&src=wedding`;
    // 腾讯原生 scheme
    const scheme = `qqmap://map/marker?marker=coord:${lat},${lng};title:${encodeURIComponent(name)};addr:${encodeURIComponent(address)}&src=wedding`;
    launchNative(scheme, webUrl);
  } else {
    const webUrl = `https://apis.map.qq.com/uri/v1/search?keyword=${encodeURIComponent(address)}&referer=wedding&src=wedding`;
    openH5(webUrl);
  }
}

/**
 * 打开 Apple Maps（仅 iOS/macOS）
 */
export function openAppleMap(options: NavOptions): void {
  const { address, lat, lng, name = '婚礼现场' } = options;
  if (lat && lng) {
    const url = `https://maps.apple.com/?q=${encodeURIComponent(name)}&ll=${lat},${lng}&t=m`;
    openH5(url);
  } else {
    const url = `https://maps.apple.com/?q=${encodeURIComponent(address)}`;
    openH5(url);
  }
}

export type MapType = 'amap' | 'bmap' | 'tencent' | 'system';

/**
 * 统一调度入口
 */
export function openNav(type: MapType, options: NavOptions): void {
  switch (type) {
    case 'amap':
      openAmapNavigation(options);
      break;
    case 'bmap':
      openBmapNav(options);
      break;
    case 'tencent':
      openTencentMapNav(options);
      break;
    case 'system':
    default:
      // 系统地图：iOS 用 Apple Maps，否则用腾讯地图降级
      if (/iphone|ipad|ipod|mac/i.test(navigator.userAgent)) {
        openAppleMap(options);
      } else {
        openTencentMapNav(options);
      }
      break;
  }
}