import { memo, useRef } from 'react';
import { motion, useScroll, useTransform } from 'framer-motion';
import SectionWrapper from '@/components/SectionWrapper';
import FloralHeartDecor from '@/components/FloralHeartDecor';
import TypewriterText from '@/components/TypewriterText';
import { MOCK_STORY_NODES, MOCK_STORY_PROSE } from '@/data/wedding';
import LoveMapTrail from '@/components/LoveMapTrail';
import { Heart } from 'lucide-react';

// 前景金色粒子分布
const GOLD_PARTICLES = [
  { left: '8%', top: '15%', size: 4 },
  { left: '85%', top: '30%', size: 3 },
  { left: '15%', top: '60%', size: 3 },
  { left: '90%', top: '75%', size: 4 },
  { left: '45%', top: '8%', size: 2 },
  { left: '70%', top: '50%', size: 3 },
];

function StorySection({ storyUnlocked }: { storyUnlocked: boolean }) {
  const sectionRef = useRef<HTMLDivElement>(null);
  const { scrollYProgress } = useScroll({
    target: sectionRef,
    offset: ['start end', 'end start'],
  });

  // 视差映射：背景层慢速 30→-30，前景层快速 -50→50
  // 移动端克制：幅度控制在 20-50px
  const bgY = useTransform(scrollYProgress, [0, 1], [30, -30]);
  const fgY = useTransform(scrollYProgress, [0, 1], [-50, 50]);

  return (
    <SectionWrapper id="story">
      <div ref={sectionRef} className="relative">
        {/* ── 背景视差层：花卉装饰慢速 ── */}
        <motion.div
          className="pointer-events-none absolute -inset-10 z-0"
          style={{ y: bgY }}
          aria-hidden="true"
        >
          <FloralHeartDecor className="absolute -left-4 top-10 h-20 w-20 opacity-40" variant="heartOnly" />
          <FloralHeartDecor className="absolute -right-4 bottom-24 h-16 w-16 opacity-30" variant="heartOnly" />
          <svg className="absolute right-8 top-1/3 h-24 w-24 opacity-20" viewBox="0 0 200 200" fill="none" stroke="#C9A961" strokeWidth="1.2">
            <path d="M10 60 C40 40 70 50 90 80 C100 95 95 115 80 120" strokeLinecap="round" />
            <circle cx="88" cy="82" r="6" />
          </svg>
        </motion.div>

        {/* ── 前景视差层：金色粒子快速 ── */}
        <motion.div
          className="pointer-events-none absolute -inset-10 z-20"
          style={{ y: fgY }}
          aria-hidden="true"
        >
          {GOLD_PARTICLES.map((p, i) => (
            <div
              key={i}
              className="absolute rounded-full"
              style={{
                left: p.left,
                top: p.top,
                width: p.size,
                height: p.size,
                background: 'rgba(212,175,55,0.45)',
                boxShadow: '0 0 8px rgba(212,175,55,0.35)',
              }}
            />
          ))}
        </motion.div>

        {/* ── 标题（仅彩蛋解锁后显示「我们的故事」）── */}
        {storyUnlocked && (
          <div className="relative z-10 text-center">
            <FloralHeartDecor className="absolute -left-2 -top-4 z-0 h-16 w-16 opacity-50" variant="heartOnly" />
            <p className="text-xs tracking-[0.3em] text-muted-foreground">OUR STORY</p>
            <h2
              className="mt-2 text-2xl font-light tracking-wider md:text-3xl"
              style={{
                fontFamily: "'Playfair Display', 'Noto Serif SC', serif",
                background: 'linear-gradient(135deg, #C9A961 0%, #F4E4BC 50%, #C9A961 100%)',
                WebkitBackgroundClip: 'text',
                backgroundClip: 'text',
                WebkitTextFillColor: 'transparent',
              }}
            >
              我们的故事
            </h2>
            <div className="mx-auto mt-3 flex items-center justify-center gap-3">
              <div
                className="h-px w-10"
                style={{ background: 'linear-gradient(90deg, transparent, #C9A961)' }}
              />
              <Heart className="h-4 w-4 fill-primary/30 text-primary/70" />
              <div
                className="h-px w-10"
                style={{ background: 'linear-gradient(90deg, #C9A961, transparent)' }}
              />
            </div>
          </div>
        )}

        {/* ── 叙事正文（仅彩蛋解锁后显示）── */}
        {storyUnlocked && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, margin: '-80px' }}
            transition={{ duration: 0.8 }}
            className="relative z-10 mx-auto mt-10 max-w-xl space-y-4 px-2"
          >
            {MOCK_STORY_PROSE.map((p, i) => (
              <motion.p
                key={i}
                initial={{ opacity: 0, y: 16 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, margin: '-60px' }}
                transition={{ duration: 0.6, delay: i * 0.08, ease: [0.16, 1, 0.3, 1] }}
                className="text-[15px] leading-[1.9] text-foreground/80 md:text-base"
                style={{ fontFamily: "'Noto Serif SC', serif" }}
              >
                {p}
              </motion.p>
            ))}
          </motion.div>
        )}

        {/* ── 我们的爱情轨迹（时间轴小标题）── */}
        <motion.div
          initial={{ opacity: 0, y: 16 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-60px' }}
          transition={{ duration: 0.6 }}
          className={`relative z-10 ${storyUnlocked ? 'mt-14' : 'mt-6'} text-center`}
        >
          <p className="text-xs tracking-[0.3em] text-muted-foreground">LOVE TIMELINE</p>
          <h3
            className="mt-1 text-lg font-medium"
            style={{
              fontFamily: "'Noto Serif SC', serif",
              background: 'linear-gradient(135deg, #C9A961, #D4AF37)',
              WebkitBackgroundClip: 'text',
              backgroundClip: 'text',
              WebkitTextFillColor: 'transparent',
            }}
          >
            我们的爱情轨迹
          </h3>
          <div className="mx-auto mt-2 flex items-center justify-center gap-2">
            <div
              className="h-px w-8"
              style={{ background: 'linear-gradient(90deg, transparent, #C9A961)' }}
            />
            <Heart className="h-3 w-3 fill-primary/30 text-primary/70" />
            <div
              className="h-px w-8"
              style={{ background: 'linear-gradient(90deg, #C9A961, transparent)' }}
            />
          </div>
        </motion.div>

        {/* ── 时间线 ── */}
        <div className="relative z-10 mt-10 space-y-10">
          {/* 金色中轴线 */}
          <div
            aria-hidden="true"
            className="absolute left-1/2 top-0 h-full w-px -translate-x-1/2"
            style={{
              background: 'linear-gradient(180deg, transparent, rgba(212,175,55,0.4) 10%, rgba(244,228,188,0.5) 50%, rgba(212,175,55,0.4) 90%, transparent)',
            }}
          />

          {MOCK_STORY_NODES.map((node, index) => {
            const isLeft = index % 2 === 0;
            return (
              <motion.div
                key={node.id}
                initial={{ opacity: 0, x: isLeft ? -40 : 40 }}
                whileInView={{ opacity: 1, x: 0 }}
                viewport={{ once: true, margin: '-60px' }}
                transition={{ duration: 0.7, delay: index * 0.1, ease: [0.16, 1, 0.3, 1] }}
                className={`relative flex items-start ${isLeft ? 'justify-start pr-[52%]' : 'justify-end pl-[52%]'}`}
              >
                {/* 中心圆点 - 带金色光晕 */}
                <div className="absolute left-1/2 top-3 -translate-x-1/2">
                  <div
                    className="flex h-4 w-4 items-center justify-center rounded-full border-2 border-primary bg-background"
                    style={{ boxShadow: '0 0 0 4px rgba(212,175,55,0.15), 0 0 8px rgba(212,175,55,0.2)' }}
                  >
                    <div className="h-1.5 w-1.5 rounded-full bg-primary" />
                  </div>
                </div>

                <div className={`w-full ${isLeft ? 'text-right' : 'text-left'}`}>
                  <p
                    className="text-xs font-medium"
                    style={{
                      background: 'linear-gradient(135deg, #C9A961, #D4AF37)',
                      WebkitBackgroundClip: 'text',
                      backgroundClip: 'text',
                      WebkitTextFillColor: 'transparent',
                    }}
                  >
                    {node.year} · {node.season}
                  </p>
                  <h3
                    className="mt-1 text-base font-semibold text-foreground md:text-lg"
                    style={{ fontFamily: "'Noto Serif SC', serif" }}
                  >
                    {node.title}
                  </h3>
                  <p className="mt-2 text-sm leading-relaxed text-muted-foreground">
                    <TypewriterText text={node.description} speed={40} />
                  </p>
                </div>
              </motion.div>
            );
          })}
        </div>

        {/* ── 爱情地图轨迹 ── */}
        <LoveMapTrail />
      </div>
    </SectionWrapper>
  );
}

export default memo(StorySection);
