import { useState, useCallback, useRef, memo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Ticket, X, Download } from 'lucide-react';
import { MOCK_WEDDING_INFO } from '@/data/wedding';

/**
 * 请柬人格化 · 专属海报（C3）
 * 宾客输入姓名 + 称谓 → canvas 合成一张专属邀请海报：
 * "诚邀 · XXX 先生/女士"，香槟金边框 + 新人落款 + 日期。
 * 微信内长按保存，转发出去的是"写着自己名字的请柬"。
 */

type Title = '先生' | '女士' | '全家';
const TITLES: Title[] = ['先生', '女士', '全家'];

/** canvas 绘制海报，返回 dataURL */
function drawPoster(name: string, title: Title): string {
  const W = 750;
  const H = 1200;
  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');
  if (!ctx) return '';

  const GOLD = '#C9A961';
  const GOLD_LIGHT = '#F4E4BC';
  const GOLD_DARK = '#B8973F';
  const TEXT = '#5C3A2E';
  const TEXT_MUTED = '#8B6B4A';

  // 背景：象牙白 + 微妙径向暖光
  const bg = ctx.createLinearGradient(0, 0, 0, H);
  bg.addColorStop(0, '#FBF7EF');
  bg.addColorStop(0.5, '#FAF5EB');
  bg.addColorStop(1, '#F5EDE0');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  const glow = ctx.createRadialGradient(W / 2, H * 0.42, 40, W / 2, H * 0.42, W * 0.85);
  glow.addColorStop(0, 'rgba(212,175,55,0.10)');
  glow.addColorStop(1, 'rgba(212,175,55,0)');
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, W, H);

  // 双线金框
  ctx.strokeStyle = GOLD;
  ctx.lineWidth = 2.5;
  ctx.strokeRect(48, 48, W - 96, H - 96);
  ctx.strokeStyle = 'rgba(201,169,97,0.45)';
  ctx.lineWidth = 1;
  ctx.strokeRect(62, 62, W - 124, H - 124);

  // 四角花纹（简单曲线 + 圆点）
  const corner = (cx: number, cy: number, sx: number, sy: number) => {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(sx, sy);
    ctx.strokeStyle = GOLD;
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(0, 46);
    ctx.bezierCurveTo(4, 20, 20, 4, 46, 0);
    ctx.stroke();
    ctx.fillStyle = GOLD_LIGHT;
    ctx.beginPath();
    ctx.arc(30, 12, 3.4, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = GOLD;
    ctx.beginPath();
    ctx.arc(12, 30, 3, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  };
  corner(80, 80, 1, 1);
  corner(W - 80, 80, -1, 1);
  corner(80, H - 80, 1, -1);
  corner(W - 80, H - 80, -1, -1);

  const center = (text: string, y: number, font: string, color: string, letterSpacing = 0) => {
    ctx.font = font;
    ctx.fillStyle = color;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    if (letterSpacing > 0 && 'letterSpacing' in ctx) {
      (ctx as CanvasRenderingContext2D & { letterSpacing: string }).letterSpacing = `${letterSpacing}px`;
    }
    ctx.fillText(text, W / 2, y);
    if ('letterSpacing' in ctx) {
      (ctx as CanvasRenderingContext2D & { letterSpacing: string }).letterSpacing = '0px';
    }
  };

  // 顶部
  center('WEDDING INVITATION', 150, '500 22px "Playfair Display", Georgia, serif', GOLD_DARK, 6);
  center('婚 礼 邀 请', 200, '300 34px "Noto Serif SC", serif', GOLD_DARK, 8);

  // 分隔线
  ctx.strokeStyle = GOLD;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(W / 2 - 90, 240);
  ctx.lineTo(W / 2 - 14, 240);
  ctx.moveTo(W / 2 + 14, 240);
  ctx.lineTo(W / 2 + 90, 240);
  ctx.stroke();
  ctx.fillStyle = GOLD;
  ctx.beginPath();
  ctx.arc(W / 2, 240, 3, 0, Math.PI * 2);
  ctx.fill();

  // 新人名（金色渐变）
  const nameGrad = ctx.createLinearGradient(0, 330, 0, 420);
  nameGrad.addColorStop(0, '#B8973F');
  nameGrad.addColorStop(0.5, '#D4AF37');
  nameGrad.addColorStop(1, '#B8973F');
  ctx.font = '300 64px "Noto Serif SC", serif';
  ctx.fillStyle = nameGrad;
  ctx.textAlign = 'center';
  ctx.fillText(`${MOCK_WEDDING_INFO.groomName}`, W / 2, 340);
  ctx.font = '300 34px "Noto Serif SC", serif';
  ctx.fillText('&', W / 2, 398);
  ctx.font = '300 64px "Noto Serif SC", serif';
  ctx.fillText(`${MOCK_WEDDING_INFO.brideName}`, W / 2, 462);

  // 诚邀对象
  center('谨 定 于', 560, '300 24px "Noto Serif SC", serif', TEXT_MUTED, 6);
  center(MOCK_WEDDING_INFO.weddingDate, 610, '400 32px "Noto Serif SC", serif', TEXT);
  center(MOCK_WEDDING_INFO.lunarDate, 652, '300 20px "Noto Serif SC", serif', TEXT_MUTED);

  center('诚 邀', 740, '300 28px "Noto Serif SC", serif', TEXT_MUTED, 10);
  center(`${name} ${title}`, 806, '500 52px "Noto Serif SC", serif', TEXT, 4);
  center('莅临见证我们的幸福时刻', 868, '300 24px "Noto Serif SC", serif', TEXT_MUTED, 4);

  // 地点
  center('· 婚礼地点 ·', 940, '300 20px "Noto Serif SC", serif', GOLD_DARK, 4);
  center(MOCK_WEDDING_INFO.location, 972, '300 20px "Noto Serif SC", serif', TEXT_MUTED);

  // 底部落款
  ctx.strokeStyle = 'rgba(201,169,97,0.6)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(W / 2 - 70, 1030);
  ctx.lineTo(W / 2 + 70, 1030);
  ctx.stroke();
  center('敬邀', 1066, '300 22px "Noto Serif SC", serif', TEXT_MUTED, 8);
  center('施郑嘉毅 · 徐春慧', 1108, '400 30px "Noto Serif SC", serif', GOLD_DARK, 6);

  return canvas.toDataURL('image/jpeg', 0.92);
}

function InvitationPoster() {
  const [name, setName] = useState('');
  const [title, setTitle] = useState<Title>('先生');
  const [posterUrl, setPosterUrl] = useState('');

  const inputRef = useRef<HTMLInputElement>(null);

  const handleGenerate = useCallback(() => {
    const trimmed = name.trim();
    if (!trimmed) {
      inputRef.current?.focus();
      return;
    }
    const url = drawPoster(trimmed, title);
    if (url) setPosterUrl(url);
  }, [name, title]);

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.7, delay: 0.85 }}
      className="relative z-10 mx-auto mt-6 max-w-sm rounded-2xl p-5 text-left"
      style={{
        background: 'rgba(255,255,240,0.85)',
        backdropFilter: 'blur(10px)',
        border: '1px solid rgba(212,175,55,0.25)',
        boxShadow: '0 4px 20px rgba(184,151,63,0.08)',
      }}
    >
      <div className="flex items-center gap-2">
        <Ticket className="h-4 w-4" style={{ color: '#D4AF37' }} />
        <span
          className="text-sm font-medium"
          style={{ fontFamily: "'Noto Serif SC', serif", color: '#8B6B4A' }}
        >
          专属请柬 · 写着你的名字
        </span>
      </div>
      <p className="mt-1.5 text-xs text-muted-foreground">
        输入姓名，生成一张只属于你的邀请海报，长按保存或转发
      </p>

      <div className="mt-3 flex items-center gap-2 rounded-xl px-3.5 py-2.5" style={{ background: 'rgba(201,169,97,0.06)', border: '1px solid rgba(201,169,97,0.25)' }}>
        <input
          ref={inputRef}
          type="text"
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="你的名字"
          maxLength={12}
          className="w-full bg-transparent text-sm outline-none placeholder:text-muted-foreground/60"
          style={{ fontFamily: "'Noto Serif SC', serif", color: '#5C3A2E' }}
          onKeyDown={(e) => {
            if (e.key === 'Enter') handleGenerate();
          }}
        />
        <div className="flex shrink-0 gap-1">
          {TITLES.map((t) => (
            <button
              key={t}
              type="button"
              onClick={() => setTitle(t)}
              className="rounded-full px-2 py-0.5 text-[11px] transition-colors"
              style={{
                background: title === t ? 'linear-gradient(135deg, #D4AF37, #C9A961)' : 'transparent',
                color: title === t ? '#FAF3E3' : '#B8973F',
                border: '1px solid rgba(201,169,97,0.35)',
                fontFamily: "'Noto Serif SC', serif",
              }}
            >
              {t}
            </button>
          ))}
        </div>
      </div>

      <button
        type="button"
        onClick={handleGenerate}
        disabled={!name.trim()}
        className="mt-3 flex w-full items-center justify-center gap-2 rounded-xl py-2.5 text-sm font-medium transition-all disabled:opacity-50"
        style={{
          background: 'linear-gradient(135deg, #D4AF37, #C9A961)',
          color: '#FAF3E3',
        }}
      >
        <Download className="h-4 w-4" />
        生成我的专属请柬
      </button>

      {/* 生成结果弹层 */}
      <AnimatePresence>
        {posterUrl && (
          <motion.div
            key="poster-modal"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[9995] flex items-center justify-center p-6"
            style={{ background: 'rgba(60,40,25,0.72)', backdropFilter: 'blur(8px)' }}
            onClick={() => setPosterUrl('')}
          >
            <motion.div
              initial={{ scale: 0.85, y: 30 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.9, opacity: 0, transition: { duration: 0.25 } }}
              transition={{ type: 'spring', stiffness: 200, damping: 22 }}
              className="relative max-h-[86vh] w-full max-w-xs overflow-hidden rounded-xl"
              onClick={(e) => e.stopPropagation()}
            >
              <img
                src={posterUrl}
                alt={`专属请柬 - ${name}`}
                className="w-full rounded-xl"
                style={{ boxShadow: '0 12px 48px rgba(0,0,0,0.35)' }}
              />
              <p
                className="mt-3 text-center text-xs"
                style={{ color: 'rgba(255,252,240,0.9)', fontFamily: "'Noto Serif SC', serif" }}
              >
                ✦ 长按图片保存专属请柬 ✦
              </p>
              <button
                type="button"
                onClick={() => setPosterUrl('')}
                aria-label="关闭"
                className="absolute right-2 top-2 flex h-8 w-8 items-center justify-center rounded-full"
                style={{ background: 'rgba(60,40,25,0.55)', color: '#FAF3E3' }}
              >
                <X className="h-4 w-4" />
              </button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

export default memo(InvitationPoster);
