import { memo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { SECTION_ANCHORS } from '@/lib/constants';
import { NavLink } from '@lark-apaas/client-toolkit-lite';

interface DotNavProps {
  activeId: string;
  anchors?: { id: string; label: string }[];
}

function DotNav({ activeId, anchors = SECTION_ANCHORS }: DotNavProps) {
  return (
    <nav
      aria-label="页面导航"
      className="fixed right-3 top-1/2 z-40 -translate-y-1/2 md:right-6"
    >
      <ul className="flex flex-col gap-3">
        {anchors.map((item) => {
          const isActive = activeId === item.id;
          return (
            <li key={item.id}>
              <NavLink
                to={`#${item.id}`}
                className="group relative flex items-center justify-end gap-2"
                aria-label={item.label}
              >
                <AnimatePresence>
                  {isActive && (
                    <motion.span
                      initial={{ opacity: 0, x: 8 }}
                      animate={{ opacity: 1, x: 0 }}
                      exit={{ opacity: 0, x: 8 }}
                      transition={{ duration: 0.2 }}
                      className="pointer-events-none whitespace-nowrap rounded-full bg-white/90 px-3 py-1 text-xs text-foreground shadow-md backdrop-blur-md"
                    >
                      {item.label}
                    </motion.span>
                  )}
                </AnimatePresence>
                <span
                  className={`block h-2.5 w-2.5 rounded-full border transition-all duration-300 ${
                    isActive
                      ? 'scale-125 border-primary bg-primary shadow-[0_0_8px_rgba(212_175_55_0.6)]'
                      : 'border-primary/50 bg-white/70 group-hover:border-primary group-hover:bg-primary/30'
                  }`}
                />
              </NavLink>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}

export default memo(DotNav);
