import { useEffect, useRef, memo } from 'react';
import { useInViewSection } from '@/hooks/use-inview-section';
import { SECTION_ANCHORS } from '@/lib/constants';
import { useIsMobile } from '@/hooks/use-mobile';

/**
 * 全局滚动花瓣特效
 * 监听板块切换，每次切换触发一波柔和花瓣从顶部飘落（约2.5秒）
 */
function ScrollPetalFX() {
  const isMobile = useIsMobile();
  const sectionIds = SECTION_ANCHORS.map((s) => s.id);
  const activeId = useInViewSection({ sectionIds, offset: isMobile ? 100 : 150 });
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const rafRef = useRef<number | null>(null);
  const petalsRef = useRef<Particle[]>([]);
  const lastSectionRef = useRef<string>('');
  const startTimeRef = useRef(0);

  // 花瓣颜色（柔和暖调）
  const COLORS = [
    'rgba(212,165,165,0.6)',
    'rgba(232,196,196,0.5)',
    'rgba(212,175,55,0.4)',
    'rgba(201,169,97,0.4)',
    'rgba(245,222,179,0.5)',
    'rgba(244,228,188,0.5)',
  ];

  interface Particle {
    x: number; y: number; vx: number; vy: number;
    size: number; rotation: number; rotSpeed: number;
    opacity: number; color: string;
  }

  // 监听板块切换
  useEffect(() => {
    if (!activeId || activeId === lastSectionRef.current) return;
    lastSectionRef.current = activeId;

    // 跳过首次（初始加载不触发）
    if (startTimeRef.current === 0) {
      startTimeRef.current = performance.now();
      return;
    }

    // 无障碍降级
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

    // 触发一波花瓣
    spawnPetals(16);
  }, [activeId]);

  const spawnPetals = (count: number) => {
    const vw = window.innerWidth;
    const petals: Particle[] = [];
    for (let i = 0; i < count; i++) {
      petals.push({
        x: Math.random() * vw,
        y: -30 - Math.random() * 100,
        vx: -0.4 + Math.random() * 0.8,
        vy: 0.6 + Math.random() * 1.2,
        size: 8 + Math.random() * 16,
        rotation: Math.random() * 360,
        rotSpeed: -1.2 + Math.random() * 2.4,
        opacity: 0.5 + Math.random() * 0.4,
        color: COLORS[Math.floor(Math.random() * COLORS.length)],
      });
    }
    petalsRef.current = petals;
    startTimeRef.current = performance.now();

    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    animate();
  };

  const animate = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const dpr = window.devicePixelRatio || 1;

    if (canvas.width !== vw * dpr) {
      canvas.width = vw * dpr;
      canvas.height = vh * dpr;
      canvas.style.width = `${vw}px`;
      canvas.style.height = `${vh}px`;
      ctx.scale(dpr, dpr);
    }

    const drawPetal = (p: Particle) => {
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate((p.rotation * Math.PI) / 180);
      ctx.globalAlpha = p.opacity;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.ellipse(0, 0, p.size / 2, (p.size / 2) * 1.6, 0, 0, Math.PI * 2);
      ctx.fill();
      // 高光
      ctx.fillStyle = 'rgba(255,255,255,0.2)';
      ctx.beginPath();
      ctx.ellipse(-p.size * 0.08, -p.size * 0.12, p.size * 0.08, p.size * 0.12, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    };

    const loop = () => {
      const elapsed = performance.now() - startTimeRef.current;
      ctx.clearRect(0, 0, vw, vh);

      let alive = false;
      for (const p of petalsRef.current) {
        if (p.y > vh + 30) continue;
        alive = true;
        p.x += p.vx + Math.sin((p.y + p.x) * 0.01) * 0.4;
        p.y += p.vy;
        p.rotation += p.rotSpeed;
        // 逐渐加速
        p.vy += 0.005;
        // 后半段淡出
        if (elapsed > 1800) {
          p.opacity = Math.max(0, p.opacity - 0.008);
        }
        drawPetal(p);
      }

      if (alive && elapsed < 3000) {
        rafRef.current = requestAnimationFrame(loop);
      } else {
        ctx.clearRect(0, 0, vw, vh);
        petalsRef.current = [];
      }
    };

    rafRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => {
    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      className="pointer-events-none fixed inset-0 z-[9998]"
      aria-hidden="true"
    />
  );
}

export default memo(ScrollPetalFX);
