import { memo, useEffect, useState, useCallback, useRef } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import DotNav from '@/components/DotNav';
import TouchHeartRipple from '@/components/TouchHeartRipple';
import EnvelopeOpening from '@/components/EnvelopeOpening';
import ScrollPetalFX from '@/components/ScrollPetalFX';
import LiveScheduleBar from '@/components/LiveScheduleBar';
import GoldenThread from '@/components/GoldenThread';
import GoldConfetti from '@/components/GoldConfetti';
import HeroSection from './sections/HeroSection';
import CountdownSection from './sections/CountdownSection';
import StorySection from './sections/StorySection';
import GallerySection from './sections/GallerySection';
import VideoSection from './sections/VideoSection';
import WeddingInfoSection from './sections/WeddingInfoSection';
import ScheduleSection from './sections/ScheduleSection';
import EndingSection from './sections/EndingSection';
import { useInViewSection } from '@/hooks/use-inview-section';
import { useShakeDetection } from '@/hooks/use-shake-detection';
import { useSeasonTint } from '@/hooks/use-season-tint';
import { SECTION_ANCHORS, SHAKE_BLESSINGS, WEDDING_MUSIC_URL } from '@/lib/constants';
import { useIsMobile } from '@/hooks/use-mobile';
import { useMusicState } from '@/hooks/use-wedding-storage';
import { useWechatShare } from '@/hooks/use-wechat-share';

function WeddingInvitationPage() {
  const isMobile = useIsMobile();
  const [storyUnlocked, setStoryUnlocked] = useState(false);

  // 爱情轨迹与爱情足迹常驻展示；「我们的故事」叙事正文由封面 9 击彩蛋解锁
  const visibleAnchors = SECTION_ANCHORS;
  const sectionIds = visibleAnchors.map((s) => s.id);
  const activeId = useInViewSection({ sectionIds, offset: isMobile ? 100 : 150 });
  const [shakeBlessing, setShakeBlessing] = useState<string | null>(null);
  const [confettiCount, setConfettiCount] = useState(0);
  const { isPlaying, setPlaying } = useMusicState();
  const seasonTintRef = useSeasonTint();

  // 微信 JS-SDK 分享（非微信环境自动跳过）
  useWechatShare();

  // 页面级 audio ref —— 关键：在用户手势内直接调用 play()
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    document.title = '我们结婚啦 - 施郑嘉毅 & 徐春慧的婚礼邀请';
  }, []);

  // 创建共享 Audio 元素
  useEffect(() => {
    const audio = new Audio();
    audio.loop = true;
    audio.volume = 0.45;
    // 只预载元数据：避免页面加载时下载整首音乐，点击信封触发 play() 时再按需加载
    audio.preload = 'metadata';
    audio.src = WEDDING_MUSIC_URL;
    audioRef.current = audio;

    const handleError = () => {
      console.warn('[wedding] audio load error:', audio.error?.code);
    };
    audio.addEventListener('error', handleError);

    return () => {
      audio.pause();
      audio.removeEventListener('error', handleError);
      audioRef.current = null;
    };
  }, []);

  // ⚡ 直接在用户手势回调中调用 play()（非 setTimeout / 非 state→useEffect）
  // 信封点击 → 此函数在同一个 call stack 内执行 → 浏览器允许带声音播放
  const handleEnvelopeOpen = useCallback(() => {
    const audio = audioRef.current;
    if (audio) {
      audio.muted = false;
      audio.volume = 0.45;
      audio.play()
        .then(() => setPlaying(true))
        .catch(() => {
          // 某些浏览器即使有用户手势也可能拒绝，静音重试
          audio.muted = true;
          audio.play()
            .then(() => {
              audio.muted = false;
              setPlaying(true);
            })
            .catch(() => {});
        });
    }
  }, [setPlaying]);

  const toggleMusic = useCallback(() => {
    const audio = audioRef.current;
    if (!audio) return;
    if (isPlaying) {
      audio.pause();
      setPlaying(false);
    } else {
      audio.play().then(() => setPlaying(true)).catch(() => {});
    }
  }, [isPlaying, setPlaying]);

  // 视频联动：调整背景音乐音量（视频播放时降低，视频暂停/静音时恢复）
  const setMusicVolume = useCallback(
    (v: number) => {
      const audio = audioRef.current;
      if (!audio) return;
      // 仅当音乐正在播放时才调整音量（用户手动暂停时不要重启）
      if (audio.paused) return;
      audio.volume = v;
    },
    []
  );

  // 摇一摇 → 随机祝福 + 金色彩带 + 分享给好友
  const handleShake = useCallback(() => {
    const blessing = SHAKE_BLESSINGS[Math.floor(Math.random() * SHAKE_BLESSINGS.length)];
    setShakeBlessing(blessing);
    setConfettiCount((c) => c + 1);
    // 触发分享引导
    window.dispatchEvent(new CustomEvent('wedding:share'));
    setTimeout(() => setShakeBlessing(null), 3500);
  }, []);

  useShakeDetection(handleShake);

  return (
    <div ref={seasonTintRef} className="relative min-h-screen w-full bg-background text-foreground">
      <EnvelopeOpening onComplete={handleEnvelopeOpen} />

      <TouchHeartRipple />
      <ScrollPetalFX />
      <DotNav activeId={activeId} anchors={visibleAnchors} />
      <LiveScheduleBar />
      <GoldConfetti trigger={confettiCount} />

      {/* B1 金线叙事：铺满全页的滚动生长金线（置于内容之下） */}
      <GoldenThread />

      <main className="relative z-10 w-full">
        <HeroSection
          isMusicPlaying={isPlaying}
          onMusicToggle={toggleMusic}
          onStoryUnlock={() => setStoryUnlocked(true)}
        />
        <CountdownSection />
        <StorySection storyUnlocked={storyUnlocked} />
        <GallerySection />
        <VideoSection onSetMusicVolume={setMusicVolume} />
        <WeddingInfoSection />
        <ScheduleSection />
        <EndingSection />
      </main>

      <AnimatePresence>
        {shakeBlessing && (
          <motion.div
            initial={{ opacity: 0, y: -20, scale: 0.9 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -10, scale: 0.95 }}
            transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
            className="fixed left-1/2 top-20 z-[9999] -translate-x-1/2"
          >
            <div
              className="rounded-full px-6 py-3 text-center text-sm"
              style={{
                background: 'rgba(255,255,240,0.95)',
                backdropFilter: 'blur(12px)',
                WebkitBackdropFilter: 'blur(12px)',
                border: '1px solid rgba(212,175,55,0.3)',
                boxShadow: '0 8px 32px rgba(212,175,55,0.15)',
                fontFamily: "'Noto Serif SC', serif",
                color: '#5C3A2E',
              }}
            >
              {shakeBlessing}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <style>{`
        html { scroll-behavior: smooth; }
        @media (prefers-reduced-motion: reduce) {
          html { scroll-behavior: auto; }
        }
      `}</style>
    </div>
  );
}

export default memo(WeddingInvitationPage);
