import { memo } from 'react';
import { Music, Music2 } from 'lucide-react';
import { motion } from 'framer-motion';

interface FloatingMusicButtonProps {
  isPlaying: boolean;
  onToggle: () => void;
}

/**
 * 浮动音乐按钮（纯展示 + 切换）
 * 实际 Audio 元素由页面级管理，确保用户手势内 play() 不被拦截
 */
function FloatingMusicButton({ isPlaying, onToggle }: FloatingMusicButtonProps) {
  return (
    <motion.button
      onClick={onToggle}
      aria-label={isPlaying ? '暂停音乐' : '播放音乐'}
      className="group flex h-11 w-11 items-center justify-center rounded-full border border-primary/50 bg-white/40 text-primary backdrop-blur-md transition-all hover:bg-primary/15"
      whileHover={{ scale: 1.08 }}
      whileTap={{ scale: 0.95 }}
    >
      {isPlaying ? (
        <motion.div
          animate={{ rotate: 360 }}
          transition={{ duration: 8, repeat: Infinity, ease: 'linear' }}
        >
          <Music className="h-5 w-5" />
        </motion.div>
      ) : (
        <Music2 className="h-5 w-5 opacity-80" />
      )}
    </motion.button>
  );
}

export default memo(FloatingMusicButton);
