import { useState, useEffect, memo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { MOCK_SCHEDULE_ITEMS } from '@/data/wedding';

/**
 * 婚礼当天实时流程进度条
 * 只在婚礼当天（2026-10-20）08:30-17:00 显示
 * 5 个流程节点等距分布，按当前时间计算进度
 * 已过节点填金色，当前节点脉冲，未到节点灰色
 */

// 婚礼当天时间窗口（本地时区 +08:00）
const WEDDING_DAY_START_HOUR = 8.5; // 08:30 开始显示
const WEDDING_DAY_END_HOUR = 17; // 17:00 停止显示

function getWeddingDayRef(): Date {
  // 2026-10-20 00:00 +08:00
  return new Date('2026-10-20T00:00:00+08:00');
}

function LiveScheduleBar() {
  const [visible, setVisible] = useState(false);
  const [progress, setProgress] = useState(0);
  const [currentIdx, setCurrentIdx] = useState(-1);

  useEffect(() => {
    const check = () => {
      const now = new Date();
      const dayRef = getWeddingDayRef();

      // 婚礼当天的显示时间窗口
      const windowStart = new Date(dayRef.getTime() + WEDDING_DAY_START_HOUR * 3600 * 1000);
      const windowEnd = new Date(dayRef.getTime() + WEDDING_DAY_END_HOUR * 3600 * 1000);

      if (now < windowStart || now > windowEnd) {
        setVisible(false);
        return;
      }

      setVisible(true);

      // 计算流程时间点
      const scheduleTimes = MOCK_SCHEDULE_ITEMS.map((item) => {
        const [h, m] = item.time.split(':').map(Number);
        return new Date(dayRef.getTime() + (h * 60 + m) * 60 * 1000).getTime();
      });

      const nowMs = now.getTime();
      const startTime = scheduleTimes[0];
      const endTime = scheduleTimes[scheduleTimes.length - 1];

      const p = Math.max(0, Math.min(1, (nowMs - startTime) / (endTime - startTime)));
      setProgress(p);

      let idx = -1;
      for (let i = 0; i < scheduleTimes.length; i++) {
        if (nowMs >= scheduleTimes[i]) idx = i;
      }
      setCurrentIdx(idx);
    };

    check();
    const timer = setInterval(check, 30000);
    return () => clearInterval(timer);
  }, []);

  return (
    <AnimatePresence>
      {visible && (
        <motion.div
          className="fixed left-0 right-0 top-0 z-[60] px-4 pt-3"
          initial={{ y: -60, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: -60, opacity: 0 }}
          transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}
        >
          <div
            className="mx-auto max-w-md rounded-full px-4 py-2.5"
            style={{
              background: 'rgba(250, 248, 245, 0.92)',
              backdropFilter: 'blur(10px)',
              border: '1px solid rgba(212, 175, 55, 0.25)',
              boxShadow: '0 4px 16px rgba(184, 151, 63, 0.12)',
            }}
          >
            {/* 标题 */}
            <div className="mb-1.5 flex items-center justify-between">
              <span className="text-[10px] tracking-[0.2em]" style={{ color: '#B8973F' }}>
                婚礼进行中
              </span>
              {currentIdx >= 0 && currentIdx < MOCK_SCHEDULE_ITEMS.length && (
                <span className="text-[10px]" style={{ color: '#8B6B4A' }}>
                  {MOCK_SCHEDULE_ITEMS[currentIdx].title}
                </span>
              )}
            </div>

            {/* 进度条轨道 */}
            <div className="relative h-6">
              {/* 底部轨道 */}
              <div
                className="absolute left-0 right-0 top-1/2 h-1 -translate-y-1/2 rounded-full"
                style={{ background: 'rgba(201, 169, 97, 0.18)' }}
              />

              {/* 已过进度填充 */}
              <div
                className="absolute left-0 top-1/2 h-1 -translate-y-1/2 rounded-full"
                style={{
                  width: `${progress * 100}%`,
                  background: 'linear-gradient(90deg, #C9A961, #D4AF37)',
                  transition: 'width 0.8s ease',
                }}
              />

              {/* 节点圆点 */}
              <div className="absolute inset-0 flex items-center justify-between">
                {MOCK_SCHEDULE_ITEMS.map((item, i) => {
                  const isPast = i <= currentIdx;
                  const isCurrent = i === currentIdx;
                  return (
                    <div key={item.id} className="relative flex items-center">
                      {isCurrent ? (
                        <motion.div
                          className="relative"
                          animate={{ scale: [1, 1.3, 1] }}
                          transition={{ duration: 1.8, repeat: Infinity, ease: 'easeInOut' }}
                        >
                          <div
                            className="h-3 w-3 rounded-full"
                            style={{
                              background: '#D4AF37',
                              boxShadow: '0 0 0 3px rgba(212,175,55,0.2), 0 0 12px rgba(212,175,55,0.5)',
                            }}
                          />
                        </motion.div>
                      ) : (
                        <div
                          className="h-2.5 w-2.5 rounded-full"
                          style={{
                            background: isPast ? '#C9A961' : '#E5DCC8',
                            border: isPast ? 'none' : '1.5px solid rgba(201,169,97,0.4)',
                            boxShadow: isPast ? '0 0 6px rgba(201,169,97,0.3)' : 'none',
                          }}
                        />
                      )}

                      {/* 节点时间标签 */}
                      <span
                        className="absolute -bottom-4 left-1/2 -translate-x-1/2 whitespace-nowrap text-[9px]"
                        style={{
                          color: isCurrent ? '#B8973F' : isPast ? '#C9A961' : '#B4B2A9',
                          fontWeight: isCurrent ? 600 : 400,
                        }}
                      >
                        {item.time}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

export default memo(LiveScheduleBar);
