import { useEffect, useRef } from 'react';

/**
 * 章节季节调色（B3 Story 情绪色谱）
 * 滚动进度映射页面背景色温漂移：
 * 封面晨光暖白 → 故事区春粉 → 仪式区正午暖金 → 结束页暮色玫瑰金
 * 直接操作 DOM（rAF 节流），无 React 重渲染。
 */

/** 颜色停靠点：[hex, 位置] */
const TINT_STOPS: Array<[string, number]> = [
  ['#FBF7EF', 0.0], // 晨光暖白
  ['#FAF0EA', 0.3], // 春粉
  ['#F8F1DE', 0.55], // 正午暖金
  ['#F6EEE6', 0.8], // 暮色
  ['#F3E9DF', 1.0], // 玫瑰金暮色
];

function hexToRgb(hex: string): [number, number, number] {
  const n = parseInt(hex.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function interpColor(p: number): string {
  for (let i = 0; i < TINT_STOPS.length - 1; i++) {
    const [c0, p0] = TINT_STOPS[i];
    const [c1, p1] = TINT_STOPS[i + 1];
    if (p >= p0 && p <= p1) {
      const t = p1 === p0 ? 0 : (p - p0) / (p1 - p0);
      const [r0, g0, b0] = hexToRgb(c0);
      const [r1, g1, b1] = hexToRgb(c1);
      const r = Math.round(r0 + (r1 - r0) * t);
      const g = Math.round(g0 + (g1 - g0) * t);
      const b = Math.round(b0 + (b1 - b0) * t);
      return `rgb(${r}, ${g}, ${b})`;
    }
  }
  return TINT_STOPS[TINT_STOPS.length - 1][0];
}

/** 挂到页面根元素 ref，随滚动微调其 backgroundColor */
export function useSeasonTint() {
  const ref = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    let raf = 0;

    const update = () => {
      raf = 0;
      const el = ref.current;
      if (!el) return;
      const docH = document.documentElement.scrollHeight - window.innerHeight;
      const p = docH > 0 ? Math.min(1, Math.max(0, window.scrollY / docH)) : 0;
      el.style.backgroundColor = interpColor(p);
    };

    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(update);
    };

    update();
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      window.removeEventListener('scroll', onScroll);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);

  return ref;
}
