import { useState, useCallback, useEffect, memo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Hourglass, Lock, LockOpen, Send, Feather } from 'lucide-react';
import { getDataloom, scopedStorage } from '@lark-apaas/client-toolkit-lite';
import type { ICapsuleRecord } from '@/lib/types';
import { CAPSULE_OPEN_DATE } from '@/lib/constants';
import { MOCK_WEDDING_INFO } from '@/data/wedding';

/**
 * 时间胶囊（C1）跨用户共享存储层（适配器模式，三级降级）
 * 宾客写下祝福，可选择「立即展示」或「封存进胶囊」，2027-10-20 一周年开舱。
 *
 * 存储后端按可用性自动选择：
 * 1) 云函数 API（方案B，首选）：标准 HTTP 接口，任何静态托管（含 CloudStudio）
 *    都能真共享。配置 CAPSULE_API_BASE + CAPSULE_API_TOKEN 启用。
 * 2) 秒哒 dataloom 共享桶（shared）：仅当部署在秒哒运行时且登录态可用时生效。
 * 3) 本地 scopedStorage：兜底，保证输入不丢、页面不崩。
 */

// —— 云函数配置（方案B）——
// 部署云函数后填入地址；或改用构建环境变量 VITE_CAPSULE_API_BASE / VITE_CAPSULE_API_TOKEN。
const CAPSULE_API_BASE = (import.meta.env.VITE_CAPSULE_API_BASE as string | undefined)
  ?? 'https://hmbb118-7gfil6n0760df227.service.tcloudbase.com/wedding-capsule';
const CAPSULE_API_TOKEN = (import.meta.env.VITE_CAPSULE_API_TOKEN as string | undefined)
  ?? 'wedding2026jiayi';
// 云函数需提供：GET 返回 ICapsuleRecord[]；POST 接收单条记录并追加（见 scripts/capsule-fn/index.js）。

// —— 秒哒 dataloom 共享桶（仅秒哒运行时路径用）——
const CAPSULE_BUCKET_ID = 'shared';
const CAPSULE_FOLDER = 'capsule';
const LOCAL_FALLBACK_KEY = '__wedding_time_capsule';

type StoreMode = 'cloud' | 'dataloom' | 'local';

/** 给 promise 加超时，避免无运行时环境下 getDataloom / fetch 挂起 */
function withTimeout<T>(p: Promise<T>, ms: number, fallback: T): Promise<T> {
  return Promise.race([
    p,
    new Promise<T>((resolve) => window.setTimeout(() => resolve(fallback), ms)),
  ]);
}

async function getCloudApi() {
  try {
    const dataloom = await withTimeout(getDataloom(), 3000, null);
    if (!dataloom) return null;
    return dataloom.storage.from(CAPSULE_BUCKET_ID);
  } catch {
    return null;
  }
}

// —— 云函数存储（方案B，标准 HTTP 接口）——
function authHeaders(): Record<string, string> {
  const h: Record<string, string> = { 'Content-Type': 'application/json' };
  if (CAPSULE_API_TOKEN) h['x-capsule-token'] = CAPSULE_API_TOKEN;
  return h;
}

async function loadFromCloudFn(): Promise<ICapsuleRecord[] | null> {
  if (!CAPSULE_API_BASE) return null;
  try {
    const res = await withTimeout<Response | null>(
      fetch(CAPSULE_API_BASE, { headers: authHeaders() }),
      4000,
      null
    );
    if (!res || !res.ok) return null;
    const data = (await res.json()) as unknown;
    return Array.isArray(data) ? (data as ICapsuleRecord[]) : null;
  } catch {
    return null;
  }
}

async function saveToCloudFn(record: ICapsuleRecord): Promise<boolean> {
  if (!CAPSULE_API_BASE) return false;
  try {
    const res = await withTimeout<Response | null>(
      fetch(CAPSULE_API_BASE, {
        method: 'POST',
        headers: authHeaders(),
        body: JSON.stringify(record),
      }),
      4000,
      null
    );
    return !!res && res.ok;
  } catch {
    return false;
  }
}

async function loadRecords(): Promise<{ records: ICapsuleRecord[]; mode: StoreMode }> {
  // 1) 云函数 API（首选）
  const cloud = await loadFromCloudFn();
  if (cloud) return { records: cloud.sort((a, b) => b.createdAt - a.createdAt), mode: 'cloud' };

  // 2) 秒哒 dataloom 共享桶
  const api = await getCloudApi();
  if (api) {
    try {
      const { data, error } = await api.list(CAPSULE_FOLDER, { limit: 500 });
      if (!error && data && data.length > 0) {
        const recs: ICapsuleRecord[] = [];
        for (const f of data) {
          const dlPath = f.name.startsWith(`${CAPSULE_FOLDER}/`)
            ? f.name
            : `${CAPSULE_FOLDER}/${f.name}`;
          const res = await api.download(dlPath);
          if (res.error || !res.data) continue;
          try {
            const rec = JSON.parse(await res.data.text()) as ICapsuleRecord;
            if (rec && typeof rec.id === 'string') recs.push(rec);
          } catch {
            /* 跳过损坏文件 */
          }
        }
        recs.sort((a, b) => b.createdAt - a.createdAt);
        return { records: recs, mode: 'dataloom' };
      }
      // list 成功但为空 → dataloom 模式（无预设数据，起始为空）
      if (!error) return { records: [], mode: 'dataloom' };
    } catch (e) {
      console.warn('[TimeCapsule] dataloom 读取失败，降级本地:', e);
    }
  }

  // 3) 本地兜底
  try {
    const raw = scopedStorage.getItem(LOCAL_FALLBACK_KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as ICapsuleRecord[];
      if (Array.isArray(parsed)) return { records: parsed, mode: 'local' };
    }
  } catch {
    /* ignore */
  }
  return { records: [], mode: 'local' };
}

async function saveRecord(record: ICapsuleRecord, mode: StoreMode) {
  if (mode === 'cloud') {
    if (await saveToCloudFn(record)) return;
    saveLocal(record); // 云函数失败 → 本地兜底，避免丢失
    return;
  }
  if (mode === 'dataloom') {
    const api = await getCloudApi();
    if (api) {
      const path = `${CAPSULE_FOLDER}/${record.id}.json`;
      const { error } = await api.upload(path, JSON.stringify(record), {
        contentType: 'application/json',
        upsert: true,
      });
      if (!error) return;
      console.warn('[TimeCapsule] dataloom 写入失败，降级本地:', error);
    }
  }
  saveLocal(record);
}

/** 本地兜底写入 */
function saveLocal(record: ICapsuleRecord) {
  try {
    const raw = scopedStorage.getItem(LOCAL_FALLBACK_KEY);
    const arr: ICapsuleRecord[] = raw ? (JSON.parse(raw) as ICapsuleRecord[]) : [];
    if (!arr.some((r) => r.id === record.id)) arr.unshift(record);
    scopedStorage.setItem(LOCAL_FALLBACK_KEY, JSON.stringify(arr));
  } catch (e) {
    console.warn('[TimeCapsule] 本地写入失败:', e);
  }
}

/** 蜡封印章 */
function WaxSeal({ broken }: { broken?: boolean }) {
  return (
    <motion.div
      animate={broken ? { scale: [1, 1.6, 1.8], opacity: [1, 1, 0], rotate: [0, 20, 45] } : {}}
      transition={broken ? { duration: 0.7, ease: 'easeOut' } : {}}
      className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full"
      style={{
        background: 'radial-gradient(circle at 35% 30%, #D98C8C 0%, #B56B6B 55%, #9E5757 100%)',
        boxShadow: '0 2px 8px rgba(158,87,87,0.35), inset 0 1px 3px rgba(255,255,255,0.3)',
      }}
    >
      {broken ? (
        <LockOpen className="h-5 w-5 text-white/80" />
      ) : (
        <Lock className="h-5 w-5 text-white/85" />
      )}
    </motion.div>
  );
}

function TimeCapsule() {
  const [records, setRecords] = useState<ICapsuleRecord[]>([]);
  const [mode, setMode] = useState<StoreMode>('local');
  const [name, setName] = useState('');
  const [message, setMessage] = useState('');
  const [sealed, setSealed] = useState(true);
  const [submitted, setSubmitted] = useState(false);
  const [opened, setOpened] = useState(false);
  const [opening, setOpening] = useState(false);

  const isOpenTime = Date.now() >= CAPSULE_OPEN_DATE.getTime();

  // 初始化：从云端（共享）或本地加载
  useEffect(() => {
    let cancelled = false;
    (async () => {
      const { records: loaded, mode: m } = await loadRecords();
      if (!cancelled) {
        setRecords(loaded);
        setMode(m);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  // 胶囊开启时间到 → 允许开舱
  useEffect(() => {
    if (isOpenTime) setOpened(false);
  }, [isOpenTime]);

  const handleSubmit = useCallback(async () => {
    const trimmedName = name.trim();
    const trimmedMsg = message.trim();
    if (!trimmedName || !trimmedMsg) return;

    const record: ICapsuleRecord = {
      id: `user-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
      name: trimmedName,
      message: trimmedMsg,
      sealed,
      source: 'user',
      createdAt: Date.now(),
    };

    // 乐观更新：先展示，再落库
    setRecords((prev) => [record, ...prev]);
    await saveRecord(record, mode);
    setSubmitted(true);
    setName('');
    setMessage('');
    window.setTimeout(() => setSubmitted(false), 3200);
  }, [name, message, sealed, mode]);

  const handleOpenCapsule = useCallback(() => {
    if (opening) return;
    setOpening(true);
    // 蜡封碎裂动画（0.7s）→ 展示内容
    window.setTimeout(() => {
      setOpened(true);
      setOpening(false);
    }, 800);
  }, [opening]);

  const sealedRecords = records.filter((r) => r.sealed);
  const openRecords = records.filter((r) => !r.sealed);
  const showSealedContent = isOpenTime && opened;

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.7, delay: 0.8 }}
      className="relative z-10 mx-auto mt-6 max-w-sm rounded-2xl p-5 text-left"
      style={{
        background: 'rgba(255,255,240,0.85)',
        backdropFilter: 'blur(10px)',
        border: '1px solid rgba(212,165,55,0.25)',
        boxShadow: '0 4px 20px rgba(184,151,63,0.08)',
      }}
    >
      {/* 标题 */}
      <div className="flex items-center gap-2">
        <Hourglass className="h-4 w-4" style={{ color: '#D4AF37' }} />
        <span
          className="text-sm font-medium"
          style={{ fontFamily: "'Noto Serif SC', serif", color: '#8B6B4A' }}
        >
          时间胶囊 · 一周年之约
        </span>
      </div>
      <p className="mt-1.5 text-xs text-muted-foreground">
        写下祝福，可以选择当场展示，或封存进胶囊——2027年10月20日一周年时开启
      </p>

      {/* 表单 */}
      <div className="mt-3 space-y-2.5">
        <input
          type="text"
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="你的名字"
          maxLength={20}
          className="w-full rounded-xl px-3.5 py-2.5 text-sm outline-none"
          style={{
            background: 'rgba(201,169,97,0.06)',
            border: '1px solid rgba(201,169,97,0.25)',
            fontFamily: "'Noto Serif SC', serif",
            color: '#5C3A2E',
          }}
        />
        <textarea
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          placeholder="想对新人说的话…（封存后一周年才能被看到哦）"
          rows={3}
          maxLength={200}
          className="w-full resize-none rounded-xl px-3.5 py-2.5 text-sm leading-relaxed outline-none"
          style={{
            background: 'rgba(201,169,97,0.06)',
            border: '1px solid rgba(201,169,97,0.25)',
            fontFamily: "'Noto Serif SC', serif",
            color: '#5C3A2E',
          }}
        />

        {/* 封存开关 */}
        <div className="flex items-center justify-between rounded-xl px-3.5 py-2.5" style={{ background: 'rgba(212,165,165,0.08)', border: '1px solid rgba(212,165,165,0.25)' }}>
          <span className="text-xs" style={{ fontFamily: "'Noto Serif SC', serif", color: '#B07A7A' }}>
            {sealed ? '🔒 封存进时间胶囊（2027.10.20 开启）' : '💬 立即展示在下方'}
          </span>
          <button
            type="button"
            role="switch"
            aria-checked={sealed}
            onClick={() => setSealed((v) => !v)}
            className="relative h-6 w-11 shrink-0 rounded-full transition-colors"
            style={{ background: sealed ? 'linear-gradient(135deg, #D4AF37, #C9A961)' : 'rgba(201,169,97,0.25)' }}
          >
            <motion.span
              layout
              transition={{ type: 'spring', stiffness: 500, damping: 30 }}
              className="absolute top-0.5 h-5 w-5 rounded-full bg-white shadow-sm"
              style={{ left: sealed ? 22 : 2 }}
            />
          </button>
        </div>

        <button
          type="button"
          onClick={handleSubmit}
          disabled={!name.trim() || !message.trim()}
          className="flex w-full items-center justify-center gap-2 rounded-xl py-2.5 text-sm font-medium transition-all disabled:opacity-50"
          style={{
            background: 'linear-gradient(135deg, #D4AF37, #C9A961)',
            color: '#FAF3E3',
          }}
        >
          <Send className="h-4 w-4" />
          {sealed ? '封存祝福' : '送出祝福'}
        </button>
      </div>

      {/* 提交成功 */}
      <AnimatePresence>
        {submitted && (
          <motion.p
            initial={{ opacity: 0, y: 6 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            className="mt-2 text-center text-[11px]"
            style={{ color: '#B8973F', fontFamily: "'Noto Serif SC', serif" }}
          >
            {sealed ? '已封存 ♡ 一周年见' : '祝福已送达 ♡'}
          </motion.p>
        )}
      </AnimatePresence>

      {/* 立即展示的祝福 */}
      {openRecords.length > 0 && (
        <div className="mt-4 space-y-2">
          {openRecords.map((r, i) => (
            <motion.div
              key={r.id}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.08 }}
              className="rounded-xl p-3"
              style={{ background: 'rgba(212,175,55,0.06)', border: '1px dashed rgba(201,169,97,0.3)' }}
            >
              <p className="text-sm leading-relaxed" style={{ fontFamily: "'Noto Serif SC', serif", color: '#5C3A2E' }}>
                {r.message}
              </p>
              <p className="mt-1.5 text-right text-[10px] text-muted-foreground">—— {r.name}</p>
            </motion.div>
          ))}
        </div>
      )}

      {/* 封存区 */}
      {sealedRecords.length > 0 && (
        <div className="mt-4">
          <div className="flex items-center justify-between">
            <span className="text-[11px] font-medium" style={{ fontFamily: "'Noto Serif SC', serif", color: '#8B6B4A' }}>
              胶囊中封存着 {sealedRecords.length} 份祝福
            </span>
            {isOpenTime && !opened && (
              <button
                type="button"
                onClick={handleOpenCapsule}
                disabled={opening}
                className="flex items-center gap-1 rounded-full px-3 py-1 text-[11px]"
                style={{ color: '#B8973F', border: '1px solid rgba(201,169,97,0.35)' }}
              >
                <LockOpen className="h-3 w-3" />
                {opening ? '开启中…' : '开舱'}
              </button>
            )}
          </div>

          <div className="mt-2 space-y-2">
            {sealedRecords.map((r, i) => (
              <motion.div
                key={r.id}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="flex items-start gap-3 rounded-xl p-3"
                style={{
                  background: showSealedContent ? 'rgba(212,165,165,0.1)' : 'rgba(158,87,87,0.05)',
                  border: showSealedContent ? '1px dashed rgba(212,165,165,0.4)' : '1px solid rgba(158,87,87,0.15)',
                }}
              >
                {/* 蜡封：开启后碎裂消失 */}
                {!showSealedContent && <WaxSeal />}
                {showSealedContent && (
                  <motion.div
                    initial={{ scale: 0, rotate: -30 }}
                    animate={{ scale: 1, rotate: 0 }}
                    transition={{ delay: 0.15 + i * 0.12, type: 'spring', stiffness: 200, damping: 14 }}
                    className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full"
                    style={{
                      background: 'radial-gradient(circle at 35% 30%, #F4E4BC 0%, #D4AF37 100%)',
                      boxShadow: '0 2px 8px rgba(212,175,55,0.3)',
                    }}
                  >
                    <Feather className="h-5 w-5 text-white/85" />
                  </motion.div>
                )}
                <div className="min-w-0 flex-1">
                  {showSealedContent ? (
                    <>
                      <motion.p
                        initial={{ opacity: 0, y: 8 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: 0.25 + i * 0.12 }}
                        className="text-sm leading-relaxed"
                        style={{ fontFamily: "'Noto Serif SC', serif", color: '#5C3A2E' }}
                      >
                        {r.message}
                      </motion.p>
                      <p className="mt-1.5 text-right text-[10px] text-muted-foreground">—— {r.name}</p>
                    </>
                  ) : (
                    <div className="py-2">
                      <p className="text-xs" style={{ fontFamily: "'Noto Serif SC', serif", color: '#9E5757' }}>
                        🔒 {r.name} 封存了一份祝福
                      </p>
                      <p className="mt-0.5 text-[10px] text-muted-foreground">
                        将于 2027.10.20 一周年开启
                      </p>
                    </div>
                  )}
                </div>
              </motion.div>
            ))}
          </div>

          {isOpenTime && opened && (
            <motion.p
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="mt-3 text-center text-[11px]"
              style={{ color: '#B07A7A', fontFamily: "'Noto Serif SC', serif" }}
            >
              结婚一周年快乐，{MOCK_WEDDING_INFO.groomName} &amp; {MOCK_WEDDING_INFO.brideName} ♡
            </motion.p>
          )}
        </div>
      )}
    </motion.div>
  );
}

export default memo(TimeCapsule);
