import { useEffect, useRef, memo } from 'react';

/**
 * 花瓣爆发庆祝动画
 * 触发时从屏幕中心向外爆发金色花瓣+爱心粒子
 * 一次性动画，持续约 2.5s
 */
function PetalBurst({ trigger }: { trigger: boolean }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const rafRef = useRef<number | null>(null);

  useEffect(() => {
    if (!trigger) return;

    // 无障碍：减少动效偏好下跳过
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    canvas.style.width = `${window.innerWidth}px`;
    canvas.style.height = `${window.innerHeight}px`;
    ctx.scale(dpr, dpr);

    const cx = window.innerWidth / 2;
    const cy = window.innerHeight / 2;

    interface Particle {
      x: number; y: number; vx: number; vy: number;
      size: number; rotation: number; rotSpeed: number;
      opacity: number; color: string; type: 'petal' | 'heart'; gravity: number;
    }

    const COLORS = [
      'rgba(212,175,55,0.8)', 'rgba(201,169,97,0.7)',
      'rgba(232,196,196,0.7)', 'rgba(212,165,165,0.6)',
      'rgba(244,228,188,0.8)',
    ];

    const particles: Particle[] = [];
    for (let i = 0; i < 60; i++) {
      const angle = (Math.PI * 2 * i) / 60 + Math.random() * 0.3;
      const speed = 3 + Math.random() * 5;
      const isHeart = Math.random() < 0.3;
      particles.push({
        x: cx, y: cy,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed - 2,
        size: isHeart ? 8 + Math.random() * 8 : 6 + Math.random() * 14,
        rotation: Math.random() * 360,
        rotSpeed: -3 + Math.random() * 6,
        opacity: 1,
        color: COLORS[Math.floor(Math.random() * COLORS.length)],
        type: isHeart ? 'heart' : 'petal',
        gravity: 0.08 + Math.random() * 0.06,
      });
    }

    const drawHeart = (x: number, y: number, size: number, color: string, alpha: number) => {
      ctx.save();
      ctx.translate(x, y);
      ctx.globalAlpha = alpha;
      ctx.fillStyle = color;
      ctx.beginPath();
      const s = size / 12;
      ctx.moveTo(0, 3 * s);
      ctx.bezierCurveTo(-3 * s, -1 * s, -6 * s, 0, 0, 5 * s);
      ctx.bezierCurveTo(6 * s, 0, 3 * s, -1 * s, 0, 3 * s);
      ctx.fill();
      ctx.restore();
    };

    const drawPetal = (x: number, y: number, size: number, rotation: number, color: string, alpha: number) => {
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate((rotation * Math.PI) / 180);
      ctx.globalAlpha = alpha;
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.ellipse(0, 0, size / 2, size / 2 * 1.6, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    };

    let startTime = performance.now();

    const loop = (now: number) => {
      const elapsed = now - startTime;
      ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);

      for (const p of particles) {
        p.vy += p.gravity;
        p.x += p.vx;
        p.y += p.vy;
        p.rotation += p.rotSpeed;
        p.opacity = Math.max(0, 1 - elapsed / 2500);

        if (p.type === 'heart') {
          drawHeart(p.x, p.y, p.size, p.color, p.opacity);
        } else {
          drawPetal(p.x, p.y, p.size, p.rotation, p.color, p.opacity);
        }
      }

      if (elapsed < 2800) {
        rafRef.current = requestAnimationFrame(loop);
      } else {
        ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);
      }
    };

    rafRef.current = requestAnimationFrame(loop);

    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, [trigger]);

  return (
    <canvas
      ref={canvasRef}
      className="pointer-events-none fixed inset-0 z-[9997]"
      aria-hidden="true"
    />
  );
}

export default memo(PetalBurst);
