import { memo } from 'react';

type DecorVariant = 'topLeft' | 'topRight' | 'bottomLeft' | 'bottomRight' | 'heartOnly' | 'floralOnly';

/**
 * 鲜花与爱心装饰 SVG 组件
 * 浪漫婚礼风格：金色枝叶 + 豆沙粉花朵 + 爱心点缀
 */
function FloralHeartDecor({
  className = '',
  variant = 'topLeft',
}: {
  className?: string;
  variant?: DecorVariant;
}) {
  const flipX = variant === 'topRight' || variant === 'bottomRight';
  const flipY = variant === 'bottomLeft' || variant === 'bottomRight';

  const transform = [
    flipX ? 'scaleX(-1)' : '',
    flipY ? 'scaleY(-1)' : '',
  ].filter(Boolean).join(' ');

  if (variant === 'heartOnly') {
    return (
      <svg
        className={`pointer-events-none absolute z-30 ${className}`}
        viewBox="0 0 80 80"
        fill="none"
        aria-hidden="true"
      >
        {/* 大爱心 */}
        <path
          d="M40 28 C36 20 28 18 22 24 C16 30 18 40 40 56 C62 40 64 30 58 24 C52 18 44 20 40 28 Z"
          fill="rgba(232,196,196,0.15)"
          stroke="rgba(212,165,165,0.4)"
          strokeWidth="0.8"
        />
        {/* 小爱心 */}
        <path
          d="M60 50 C58 47 54 46 51 49 C48 52 50 56 60 62 C70 56 72 52 69 49 C66 46 62 47 60 50 Z"
          fill="rgba(255,182,193,0.12)"
          stroke="rgba(212,165,165,0.3)"
          strokeWidth="0.6"
        />
        {/* 闪光点 */}
        <circle cx="25" cy="35" r="1.5" fill="rgba(244,228,188,0.5)" />
        <circle cx="55" cy="45" r="1" fill="rgba(212,175,55,0.4)" />
      </svg>
    );
  }

  if (variant === 'floralOnly') {
    return (
      <svg
        className={`pointer-events-none absolute z-30 ${className}`}
        viewBox="0 0 120 120"
        fill="none"
        style={{ transform: transform || undefined }}
        aria-hidden="true"
      >
        {/* 主枝 */}
        <path d="M8 100 C20 80 35 60 55 45 C65 37 75 32 85 30" stroke="#C9A961" strokeWidth="1.2" strokeLinecap="round" />
        {/* 叶片 1 */}
        <path d="M30 72 C25 65 22 58 28 52 C34 56 38 63 35 70 Z" fill="rgba(212,175,55,0.12)" stroke="rgba(201,169,97,0.4)" strokeWidth="0.8" />
        {/* 叶片 2 */}
        <path d="M48 55 C43 48 40 40 46 34 C52 38 56 46 53 53 Z" fill="rgba(212,165,165,0.15)" stroke="rgba(212,165,165,0.35)" strokeWidth="0.8" />
        {/* 花朵 1 — 粉色 */}
        <g>
          <circle cx="55" cy="45" r="7" fill="rgba(232,196,196,0.35)" stroke="rgba(212,165,165,0.4)" strokeWidth="0.8" />
          <circle cx="55" cy="45" r="4.5" fill="rgba(232,196,196,0.25)" />
          <circle cx="55" cy="45" r="2.5" fill="rgba(201,169,97,0.5)" />
        </g>
        {/* 花瓣 */}
        <ellipse cx="50" cy="38" rx="3" ry="5" fill="rgba(232,196,196,0.2)" transform="rotate(-30 50 38)" />
        <ellipse cx="61" cy="40" rx="3" ry="5" fill="rgba(232,196,196,0.2)" transform="rotate(30 61 40)" />
        <ellipse cx="61" cy="51" rx="3" ry="5" fill="rgba(232,196,196,0.2)" transform="rotate(100 61 51)" />
        <ellipse cx="49" cy="51" rx="3" ry="5" fill="rgba(232,196,196,0.2)" transform="rotate(-100 49 51)" />
        {/* 花朵 2 — 金色 */}
        <circle cx="85" cy="30" r="5" fill="rgba(212,175,55,0.2)" stroke="rgba(201,169,97,0.4)" strokeWidth="0.8" />
        <circle cx="85" cy="30" r="2" fill="rgba(244,228,188,0.6)" />
        {/* 小花苞 */}
        <circle cx="38" cy="82" r="3" fill="rgba(232,196,196,0.3)" stroke="rgba(212,165,165,0.3)" strokeWidth="0.6" />
        <circle cx="68" cy="37" r="2.5" fill="rgba(212,175,55,0.15)" stroke="rgba(201,169,97,0.3)" strokeWidth="0.6" />
        {/* 小叶 */}
        <path d="M62 50 C58 45 57 40 62 37" stroke="rgba(201,169,97,0.35)" strokeWidth="0.8" strokeLinecap="round" />
        <path d="M22 90 C18 85 17 80 22 77" stroke="rgba(201,169,97,0.3)" strokeWidth="0.8" strokeLinecap="round" />
      </svg>
    );
  }

  // 默认：鲜花+爱心组合
  return (
    <svg
      className={`pointer-events-none absolute z-30 ${className}`}
      viewBox="0 0 130 130"
      fill="none"
      style={{ transform: transform || undefined }}
      aria-hidden="true"
    >
      {/* 主枝 */}
      <path d="M8 105 C20 85 35 65 55 50 C65 42 75 37 88 35" stroke="#C9A961" strokeWidth="1.2" strokeLinecap="round" />
      {/* 叶片 */}
      <path d="M30 78 C25 71 22 64 28 58 C34 62 38 69 35 76 Z" fill="rgba(212,175,55,0.12)" stroke="rgba(201,169,97,0.4)" strokeWidth="0.8" />
      <path d="M48 60 C43 53 40 45 46 39 C52 43 56 51 53 58 Z" fill="rgba(212,165,165,0.15)" stroke="rgba(212,165,165,0.35)" strokeWidth="0.8" />
      {/* 花朵 1 — 粉色大花 */}
      <g>
        <ellipse cx="50" cy="43" rx="4" ry="6" fill="rgba(232,196,196,0.2)" transform="rotate(-30 50 43)" />
        <ellipse cx="62" cy="43" rx="4" ry="6" fill="rgba(232,196,196,0.2)" transform="rotate(30 62 43)" />
        <ellipse cx="62" cy="55" rx="4" ry="6" fill="rgba(232,196,196,0.2)" transform="rotate(100 62 55)" />
        <ellipse cx="50" cy="55" rx="4" ry="6" fill="rgba(232,196,196,0.2)" transform="rotate(-100 50 55)" />
        <circle cx="56" cy="49" r="7" fill="rgba(232,196,196,0.35)" stroke="rgba(212,165,165,0.4)" strokeWidth="0.8" />
        <circle cx="56" cy="49" r="2.5" fill="rgba(201,169,97,0.5)" />
      </g>
      {/* 花朵 2 — 金色小花 */}
      <circle cx="88" cy="35" r="5" fill="rgba(212,175,55,0.2)" stroke="rgba(201,169,97,0.4)" strokeWidth="0.8" />
      <circle cx="88" cy="35" r="2" fill="rgba(244,228,188,0.6)" />
      {/* 小花苞 */}
      <circle cx="38" cy="88" r="3" fill="rgba(232,196,196,0.3)" stroke="rgba(212,165,165,0.3)" strokeWidth="0.6" />
      <circle cx="70" cy="41" r="2.5" fill="rgba(212,175,55,0.15)" stroke="rgba(201,169,97,0.3)" strokeWidth="0.6" />
      {/* 爱心点缀 */}
      <path
        d="M100 60 C97 56 92 55 89 58 C86 61 88 66 100 74 C112 66 114 61 111 58 C108 55 103 56 100 60 Z"
        fill="rgba(255,182,193,0.15)"
        stroke="rgba(212,165,165,0.35)"
        strokeWidth="0.8"
      />
      {/* 小爱心 */
      }
      <path
        d="M20 55 C18 52 15 51 13 53 C11 55 12 58 20 63 C28 58 29 55 27 53 C25 51 22 52 20 55 Z"
        fill="rgba(232,196,196,0.12)"
        stroke="rgba(212,165,165,0.3)"
        strokeWidth="0.6"
      />
      {/* 闪光点 */}
      <circle cx="75" cy="20" r="1.5" fill="rgba(244,228,188,0.5)" />
      <circle cx="25" cy="70" r="1" fill="rgba(212,175,55,0.4)" />
      {/* 小叶 */}
      <path d="M62 50 C58 45 57 40 62 37" stroke="rgba(201,169,97,0.35)" strokeWidth="0.8" strokeLinecap="round" />
      <path d="M22 90 C18 85 17 80 22 77" stroke="rgba(201,169,97,0.3)" strokeWidth="0.8" strokeLinecap="round" />
    </svg>
  );
}

export default memo(FloralHeartDecor);
