import { memo } from 'react';
import { motion } from 'framer-motion';

interface SectionWrapperProps {
  id: string;
  children: React.ReactNode;
  className?: string;
  delay?: number;
}

/**
 * 板块包装：入场时上下幕布向两侧拉开 + 内容淡入上浮
 * 不再用 clip-path 直接裁剪内容——在部分 WebView/旧浏览器里 clip-path 动画
 * 会卡死在初始态导致整片白板。改用两张绝对定位幕布遮挡，再用 height 动画
 * 收起，可靠性高得多。
 */
function SectionWrapper({ id, children, className = '', delay = 0 }: SectionWrapperProps) {
  return (
    <section id={id} className={`relative w-full scroll-mt-8 overflow-hidden ${className}`}>
      <motion.div
        className="relative mx-auto max-w-xl px-5 py-16 md:px-6 md:py-20"
        initial={{ opacity: 0, y: 36, scale: 0.98 }}
        whileInView={{ opacity: 1, y: 0, scale: 1 }}
        viewport={{ once: true, amount: 0.15 }}
        transition={{
          duration: 0.8,
          delay,
          ease: [0.16, 1, 0.3, 1],
        }}
      >
        {children}
      </motion.div>

      {/* 上下开帘幕布：进入视口时高度从 50% → 0，内容随之揭晓 */}
      <motion.div
        className="pointer-events-none absolute inset-x-0 top-0 z-20"
        initial={{ height: '50%' }}
        whileInView={{ height: '0%' }}
        viewport={{ once: true, amount: 0.15 }}
        transition={{
          duration: 0.85,
          delay,
          ease: [0.16, 1, 0.3, 1],
        }}
        style={{
          background:
            'linear-gradient(180deg, rgba(250,248,245,0.98) 0%, rgba(250,248,245,0.85) 70%, transparent 100%)',
        }}
      />
      <motion.div
        className="pointer-events-none absolute inset-x-0 bottom-0 z-20"
        initial={{ height: '50%' }}
        whileInView={{ height: '0%' }}
        viewport={{ once: true, amount: 0.15 }}
        transition={{
          duration: 0.85,
          delay,
          ease: [0.16, 1, 0.3, 1],
        }}
        style={{
          background:
            'linear-gradient(0deg, rgba(250,248,245,0.98) 0%, rgba(250,248,245,0.85) 70%, transparent 100%)',
        }}
      />
    </section>
  );
}

export default memo(SectionWrapper);
