import { memo, useState, useEffect, useRef, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import SectionWrapper from '@/components/SectionWrapper';
import Image from '@/components/ui/image';
import FloralHeartDecor from '@/components/FloralHeartDecor';
import type { IGalleryPhoto } from '@/lib/types';

// 从 src/assets/gallery 目录批量导入照片（构建期生成独立资源文件，按需下载）
const galleryModules = import.meta.glob(
  '@/assets/gallery/*.{jpg,jpeg,png,webp,avif,JPG,JPEG,PNG}',
  { eager: true, query: '?url', import: 'default' }
) as Record<string, string>;

// 按文件名中的数字自然排序（1, 2, 3 ... 10, 11, 12），而非字典序（1, 10, 11, 12, 2 ...）
const numericSort = (a: string, b: string) => {
  const numA = parseInt(a.match(/(\d+)/)?.[1] ?? '0', 10);
  const numB = parseInt(b.match(/(\d+)/)?.[1] ?? '0', 10);
  return numA - numB;
};

const GALLERY_PHOTOS: IGalleryPhoto[] = Object.entries(galleryModules)
  .sort(([a], [b]) => numericSort(a, b))
  .map(([path, url], i) => ({
    id: `gallery-${i}`,
    dataUrl: url,
    width: 0,
    height: 0,
    source: 'mock',
  }));

function GallerySection() {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [inView, setInView] = useState(false);
  const [currentLoaded, setCurrentLoaded] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const touchStartX = useRef(0);
  const autoTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const currentIndexRef = useRef(0);
  const prefetchedRef = useRef<Set<string>>(new Set());

  // 同步最新 index，供视口回调读取
  useEffect(() => {
    currentIndexRef.current = currentIndex;
  }, [currentIndex]);

  /**
   * 按需预取：仅预取当前图及其前后一张（循环取模）。
   * 其余图片不预加载，避免一次性并发下载导致卡顿。
   */
  const prefetchAround = useCallback((index: number) => {
    const n = GALLERY_PHOTOS.length;
    if (n === 0) return;
    const targets = [index, (index + 1) % n, (index - 1 + n) % n];
    targets.forEach((i) => {
      const url = GALLERY_PHOTOS[i]?.dataUrl;
      if (!url || prefetchedRef.current.has(url)) return;
      prefetchedRef.current.add(url);
      const img = new window.Image();
      img.decoding = 'async';
      img.src = url;
    });
  }, []);

  // 区块进入视口（提前 300px）才预取图片 → 首屏完全不加载相册资源
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          setInView(true);
          prefetchAround(currentIndexRef.current);
          observer.disconnect();
        }
      },
      { rootMargin: '300px 0px' }
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [prefetchAround]);

  // index 变化时预取相邻图
  useEffect(() => {
    if (inView) prefetchAround(currentIndex);
    setCurrentLoaded(false);
  }, [currentIndex, inView, prefetchAround]);

  const goNext = useCallback(() => {
    setCurrentIndex((i) => (i + 1) % GALLERY_PHOTOS.length);
  }, []);

  const goPrev = useCallback(() => {
    setCurrentIndex((i) => (i - 1 + GALLERY_PHOTOS.length) % GALLERY_PHOTOS.length);
  }, []);

  // 自动轮播：进入视口才启动，离开视口暂停（不产生无意义的渲染开销）
  useEffect(() => {
    const el = containerRef.current;
    if (!el || GALLERY_PHOTOS.length <= 1) return;

    const startAuto = () => {
      if (!autoTimerRef.current) {
        autoTimerRef.current = setInterval(goNext, 3800);
      }
    };
    const stopAuto = () => {
      if (autoTimerRef.current) {
        clearInterval(autoTimerRef.current);
        autoTimerRef.current = null;
      }
    };

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) startAuto();
        else stopAuto();
      },
      { threshold: 0.1 }
    );
    observer.observe(el);
    return () => {
      observer.disconnect();
      stopAuto();
    };
  }, [goNext]);

  // 触摸滑动暂停自动播放，松手后恢复
  const handleTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.touches[0].clientX;
    if (autoTimerRef.current) clearInterval(autoTimerRef.current);
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
    const dx = e.changedTouches[0].clientX - touchStartX.current;
    if (Math.abs(dx) > 40) {
      if (dx > 0) goPrev();
      else goNext();
    }
    // 恢复自动播放
    if (autoTimerRef.current) clearInterval(autoTimerRef.current);
    autoTimerRef.current = setInterval(goNext, 3800);
  };

  return (
    <SectionWrapper
      id="gallery"
      className="bg-gradient-to-b from-background via-primary/5 to-background"
    >
      <div className="text-center">
        <p className="text-xs tracking-[0.3em] text-muted-foreground">GALLERY</p>
        <h2
          className="mt-2 text-2xl font-light tracking-wider md:text-3xl"
          style={{
            fontFamily: "'Playfair Display', 'Noto Serif SC', serif",
            background: 'linear-gradient(135deg, #C9A961 0%, #F4E4BC 50%, #C9A961 100%)',
            WebkitBackgroundClip: 'text',
            backgroundClip: 'text',
            WebkitTextFillColor: 'transparent',
          }}
        >
          婚纱相册
        </h2>
        <div className="mx-auto mt-3 flex items-center justify-center gap-2">
          <span className="h-px w-12" style={{ background: 'linear-gradient(90deg, transparent, #C9A961, transparent)' }} />
          <span style={{ color: '#C9A961', fontSize: '10px' }}>✦</span>
          <span className="h-px w-12" style={{ background: 'linear-gradient(90deg, transparent, #C9A961, transparent)' }} />
        </div>
      </div>

      {/* 相册幻灯片 */}
      {GALLERY_PHOTOS.length === 0 ? null : (
        <div
          ref={containerRef}
          className="relative mt-8 flex items-center justify-center"
          style={{ height: 'min(80vh, 520px)' }}
          onTouchStart={handleTouchStart}
          onTouchEnd={handleTouchEnd}
        >
          {/* 鲜花爱心装饰 — 四角包围 */}
          <FloralHeartDecor className="left-0 top-0 h-24 w-24 md:h-32 md:w-32" variant="topLeft" />
          <FloralHeartDecor className="right-0 top-0 h-24 w-24 md:h-32 md:w-32" variant="topRight" />
          <FloralHeartDecor className="bottom-0 left-0 h-24 w-24 md:h-32 md:w-32" variant="bottomLeft" />
          <FloralHeartDecor className="bottom-0 right-0 h-24 w-24 md:h-32 md:w-32" variant="bottomRight" />

          {/* 卡片容器 —— 柔和淡入淡出：旧图放大淡出，新图缩小淡入 */}
          <div
            className="relative h-full"
            style={{
              width: 'min(88vw, 360px)',
              perspective: 1000,
            }}
          >
            <AnimatePresence mode="wait">
              {GALLERY_PHOTOS.map((photo, i) => {
                if (i !== currentIndex) return null;
                return (
                  <motion.div
                    key={photo.id}
                    className="absolute inset-0"
                    style={{
                      zIndex: 20,
                      willChange: 'transform, opacity',
                    }}
                    initial={{ scale: 0.85, opacity: 0 }}
                    animate={{ scale: 1, opacity: 1 }}
                    exit={{ scale: 1.12, opacity: 0 }}
                    transition={{
                      duration: 0.8,
                      ease: [0.25, 0.46, 0.45, 0.94],
                    }}
                    onClick={() => {
                      goNext();
                    }}
                  >
                    <div
                      className="relative h-full w-full overflow-hidden rounded-2xl"
                      style={{
                        border: '2px solid rgba(212,175,55,0.35)',
                        boxShadow: '0 20px 60px rgba(0,0,0,0.15), 0 6px 20px rgba(212,175,55,0.2)',
                      }}
                    >
                      <Image
                        src={photo.dataUrl}
                        alt={`婚礼照片 ${i + 1}`}
                        className="h-full w-full object-cover"
                        loading="eager"
                        decoding="async"
                        // 首屏可见的当前图优先加载
                        fetchPriority={i === currentIndex ? 'high' : 'auto'}
                        onLoad={() => setCurrentLoaded(true)}
                      />
                      {/* 渐变遮罩底部 */}
                      <div
                        className="pointer-events-none absolute bottom-0 left-0 right-0 h-20"
                        style={{
                          background:
                            'linear-gradient(to top, rgba(0,0,0,0.25), transparent)',
                        }}
                      />
                      {/* 当前照片序号 */}
                      <div
                        className="absolute bottom-4 left-1/2 -translate-x-1/2 rounded-full px-3 py-1 text-xs"
                        style={{
                          background: 'rgba(255,255,240,0.8)',
                          backdropFilter: 'blur(8px)',
                          color: '#8B6B4A',
                          fontFamily: "'Playfair Display', serif",
                        }}
                      >
                        {i + 1} / {GALLERY_PHOTOS.length}
                      </div>
                    </div>
                  </motion.div>
                );
              })}
            </AnimatePresence>

            {/* 图片加载中提示（仅进入视口后、当前图未就绪时短暂出现） */}
            {inView && !currentLoaded && (
              <div className="absolute inset-0 flex items-center justify-center" style={{ zIndex: 5 }}>
                <div className="text-xs text-muted-foreground/60">加载中...</div>
              </div>
            )}
          </div>

          {/* 左右切换按钮 */}
          <button
            onClick={() => { goPrev(); }}
            className="absolute left-0 top-1/2 z-20 flex h-10 w-10 -translate-y-1/2 items-center justify-center rounded-full transition-opacity hover:opacity-80"
            style={{
              background: 'rgba(255,255,240,0.7)',
              backdropFilter: 'blur(8px)',
              border: '1px solid rgba(212,175,55,0.2)',
            }}
            aria-label="上一张"
          >
            <ChevronLeft className="h-5 w-5" style={{ color: '#8B6B4A' }} />
          </button>
          <button
            onClick={() => { goNext(); }}
            className="absolute right-0 top-1/2 z-20 flex h-10 w-10 -translate-y-1/2 items-center justify-center rounded-full transition-opacity hover:opacity-80"
            style={{
              background: 'rgba(255,255,240,0.7)',
              backdropFilter: 'blur(8px)',
              border: '1px solid rgba(212,175,55,0.2)',
            }}
            aria-label="下一张"
          >
            <ChevronRight className="h-5 w-5" style={{ color: '#8B6B4A' }} />
          </button>

          {/* 底部指示器 */}
          <div className="absolute bottom-2 left-1/2 flex -translate-x-1/2 gap-1.5">
            {GALLERY_PHOTOS.map((_, i) => (
              <button
                key={i}
                onClick={() => {
                  setCurrentIndex(i);
                }}
                className="h-1.5 rounded-full transition-all"
                style={{
                  width: i === currentIndex ? 20 : 6,
                  background:
                    i === currentIndex
                      ? 'linear-gradient(90deg, #C9A961, #D4AF37)'
                      : 'rgba(212,175,55,0.25)',
                }}
                aria-label={`跳转到第 ${i + 1} 张`}
              />
            ))}
          </div>
        </div>
      )}
    </SectionWrapper>
  );
}

export default memo(GallerySection);
