import { useEffect, useRef, memo } from 'react';
import { logger } from '@lark-apaas/client-toolkit-lite';

interface PetalRainProps {
  /** 爱心数量，默认 18 */
  count?: number;
}

interface Heart {
  x: number;
  y: number;
  size: number;
  speedY: number;
  speedX: number;
  rotation: number;
  rotSpeed: number;
  opacity: number;
  color: string;
  delay: number;
}

const HEART_COLORS = [
  'rgba(212, 165, 165, 0.7)',
  'rgba(232, 196, 196, 0.6)',
  'rgba(212, 175, 55, 0.5)',
  'rgba(201, 169, 97, 0.5)',
  'rgba(245, 222, 179, 0.6)',
];

function PetalRain({ count = 18 }: PetalRainProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const rafRef = useRef<number | null>(null);
  const heartsRef = useRef<Heart[]>([]);
  const gammaRef = useRef(0); // 陀螺仪左右倾斜角 -90~90

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resize = () => {
      const dpr = window.devicePixelRatio || 1;
      canvas.width = window.innerWidth * dpr;
      canvas.height = window.innerHeight * dpr;
      canvas.style.width = `${window.innerWidth}px`;
      canvas.style.height = `${window.innerHeight}px`;
      ctx.scale(dpr, dpr);
    };
    resize();
    window.addEventListener('resize', resize);

    // 初始化爱心
    const hearts: Heart[] = [];
    for (let i = 0; i < count; i++) {
      hearts.push(createHeart(window.innerWidth, window.innerHeight, true));
    }
    heartsRef.current = hearts;

    let lastTime = performance.now();

    const drawHeart = (h: Heart) => {
      ctx.save();
      ctx.translate(h.x, h.y);
      ctx.rotate((h.rotation * Math.PI) / 180);
      ctx.globalAlpha = h.opacity;

      // 爱心形状：两段贝塞尔曲线
      const s = h.size;
      ctx.fillStyle = h.color;
      ctx.beginPath();
      ctx.moveTo(0, s * 0.38);
      ctx.bezierCurveTo(-s * 0.6, -s * 0.1, -s * 0.32, -s * 0.55, 0, -s * 0.12);
      ctx.bezierCurveTo(s * 0.32, -s * 0.55, s * 0.6, -s * 0.1, 0, s * 0.38);
      ctx.closePath();
      ctx.fill();

      // 高光
      ctx.fillStyle = 'rgba(255,255,255,0.28)';
      ctx.beginPath();
      ctx.ellipse(-s * 0.16, -s * 0.16, s * 0.1, s * 0.14, 0, 0, Math.PI * 2);
      ctx.fill();

      ctx.restore();
    };

    const loop = (now: number) => {
      const delta = (now - lastTime) / 16.67; // 归一化到 60fps 帧
      lastTime = now;

      ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);

      for (const h of heartsRef.current) {
        if (h.delay > 0) {
          h.delay -= delta * 16.67;
          continue;
        }
        h.y += h.speedY * delta;
        const wind = (gammaRef.current / 90) * 0.8; // 陀螺仪风力 -0.8~0.8
        h.x += h.speedX * delta + Math.sin((h.y + h.x) * 0.01) * 0.3 * delta + wind * delta;
        h.rotation += h.rotSpeed * delta;

        if (h.y > window.innerHeight + 30) {
          Object.assign(h, createHeart(window.innerWidth, window.innerHeight, false));
        }

        drawHeart(h);
      }

      rafRef.current = requestAnimationFrame(loop);
    };

    rafRef.current = requestAnimationFrame(loop);

    // 陀螺仪监听：手机倾斜控制爱心飘落方向
    const handleOrientation = (e: DeviceOrientationEvent) => {
      if (e.gamma !== null && e.gamma !== undefined) {
        gammaRef.current = Math.max(-90, Math.min(90, e.gamma));
      }
    };

    const startListening = () => {
      window.addEventListener('deviceorientation', handleOrientation, true);
    };
    const stopListening = () => {
      window.removeEventListener('deviceorientation', handleOrientation, true);
    };

    // iOS 13+ 需要用户手势触发权限请求
    const DAE = DeviceOrientationEvent as unknown as {
      requestPermission?: () => Promise<string>;
    };
    if (typeof DAE.requestPermission === 'function') {
      const trigger = () => {
        DAE.requestPermission?.()
          .then((state: string) => {
            if (state === 'granted') startListening();
          })
          .catch(() => {});
        window.removeEventListener('touchend', trigger);
        window.removeEventListener('pointerup', trigger);
      };
      window.addEventListener('touchend', trigger, { once: true });
      window.addEventListener('pointerup', trigger, { once: true });
    } else {
      // Android / 桌面直接监听
      startListening();
    }

    return () => {
      window.removeEventListener('resize', resize);
      stopListening();
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
      }
    };
  }, [count]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden="true"
      className="pointer-events-none absolute inset-0 z-10"
      onError={(e) => logger.error('petal canvas error:', String(e))}
    />
  );
}

function createHeart(vw: number, vh: number, initial: boolean): Heart {
  const size = 9 + Math.random() * 15;
  return {
    x: Math.random() * vw,
    y: initial ? Math.random() * vh : -30 - Math.random() * 200,
    size,
    speedY: 0.4 + Math.random() * 0.8,
    speedX: -0.3 + Math.random() * 0.6,
    rotation: Math.random() * 360,
    rotSpeed: -0.8 + Math.random() * 1.6,
    opacity: 0.4 + Math.random() * 0.5,
    color: HEART_COLORS[Math.floor(Math.random() * HEART_COLORS.length)],
    delay: initial ? Math.random() * 2000 : Math.random() * 500,
  };
}

export default memo(PetalRain);
