import { memo } from 'react';
import { motion } from 'framer-motion';

/**
 * 爱情足迹地图
 * 抽象渐变背景 + 6 地点节点 + 金色连线依次绘制
 * ⚠ 合规：不绘制任何国界/省界轮廓，仅城市点 + 抽象背景
 */

interface LoveMapNode {
  year: string;
  label: string;
  city: string;
  /** 归一化坐标 0-1 */
  coord: { x: number; y: number };
}

// 真实去过的地方（按旅程顺序）：简阳→成都→自贡→乐山→阿坝→北京
const LOVE_MAP_NODES: LoveMapNode[] = [
  { year: '2017', label: '相遇', city: '简阳', coord: { x: 0.30, y: 0.60 } },
  { year: '2024', label: '相守', city: '成都', coord: { x: 0.42, y: 0.46 } },
  { year: '同游', label: '冷吃兔', city: '自贡', coord: { x: 0.30, y: 0.78 } },
  { year: '同游', label: '大佛·钵钵鸡', city: '乐山', coord: { x: 0.50, y: 0.86 } },
  { year: '同游', label: '川西的雪', city: '阿坝', coord: { x: 0.66, y: 0.24 } },
  { year: '同游', label: '烤鸭·铜锅', city: '北京', coord: { x: 0.86, y: 0.34 } },
];

// SVG 视区尺寸
const W = 340;
const H = 280;
const PAD = 30;

function toSvg(coord: { x: number; y: number }) {
  return {
    x: PAD + coord.x * (W - PAD * 2),
    y: PAD + coord.y * (H - PAD * 2),
  };
}

/** 用平滑贝塞尔曲线依次连接节点 */
function buildPath(nodes: LoveMapNode[]): string {
  const pts = nodes.map((n) => toSvg(n.coord));
  if (pts.length < 2) return '';

  let d = `M ${pts[0].x} ${pts[0].y}`;
  for (let i = 1; i < pts.length; i++) {
    const prev = pts[i - 1];
    const curr = pts[i];
    const cx = (prev.x + curr.x) / 2;
    d += ` C ${cx} ${prev.y}, ${cx} ${curr.y}, ${curr.x} ${curr.y}`;
  }
  return d;
}

const TRAIL_PATH = buildPath(LOVE_MAP_NODES);

function LoveMapTrail() {
  return (
    <div className="relative mx-auto mt-16 max-w-sm">
      {/* 标题 */}
      <div className="mb-4 text-center">
        <p className="text-xs tracking-[0.3em] text-muted-foreground">OUR FOOTPRINTS</p>
        <h3
          className="mt-1 text-lg font-medium"
          style={{
            fontFamily: "'Noto Serif SC', serif",
            background: 'linear-gradient(135deg, #C9A961, #D4AF37)',
            WebkitBackgroundClip: 'text',
            backgroundClip: 'text',
            WebkitTextFillColor: 'transparent',
          }}
        >
          爱情足迹
        </h3>
      </div>

      {/* 地图区域 */}
      <motion.div
        initial={{ opacity: 0, y: 30 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true, margin: '-60px' }}
        transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
        className="relative overflow-hidden rounded-2xl"
        style={{
          background:
            'linear-gradient(145deg, rgba(232,196,196,0.15) 0%, rgba(250,248,245,0.9) 40%, rgba(212,175,55,0.08) 100%)',
          border: '1px solid rgba(212,175,55,0.2)',
          boxShadow: '0 4px 20px rgba(184,151,63,0.06)',
        }}
      >
        {/* 背景装饰纹理（抽象，非地图轮廓） */}
        <svg className="pointer-events-none absolute inset-0 h-full w-full opacity-30" viewBox={`0 0 ${W} ${H}`} fill="none">
          <circle cx={W * 0.75} cy={H * 0.7} r="60" stroke="rgba(201,169,97,0.15)" strokeWidth="0.5" />
          <circle cx={W * 0.75} cy={H * 0.7} r="90" stroke="rgba(201,169,97,0.08)" strokeWidth="0.5" />
          <circle cx={W * 0.2} cy={H * 0.3} r="40" stroke="rgba(212,165,165,0.15)" strokeWidth="0.5" />
          <circle cx={W * 0.2} cy={H * 0.3} r="65" stroke="rgba(212,165,165,0.08)" strokeWidth="0.5" />
        </svg>

        <svg viewBox={`0 0 ${W} ${H}`} className="relative block w-full">
          {/* 金色轨迹线 - 依次描绘动画 */}
          <motion.path
            d={TRAIL_PATH}
            fill="none"
            stroke="#C9A961"
            strokeWidth="1.8"
            strokeLinecap="round"
            strokeDasharray="6 6"
            initial={{ pathLength: 0, opacity: 0 }}
            whileInView={{ pathLength: 1, opacity: 1 }}
            viewport={{ once: true, margin: '-60px' }}
            transition={{ duration: 2.2, delay: 0.3, ease: 'easeInOut' }}
          />

          {/* 城市节点 */}
          {LOVE_MAP_NODES.map((node, i) => {
            const p = toSvg(node.coord);
            return (
              <motion.g
                key={`${node.year}-${node.city}`}
                initial={{ opacity: 0, scale: 0 }}
                whileInView={{ opacity: 1, scale: 1 }}
                viewport={{ once: true, margin: '-60px' }}
                transition={{
                  duration: 0.5,
                  delay: 0.5 + i * 0.45,
                  type: 'spring',
                  stiffness: 260,
                }}
              >
                {/* 脉冲光晕 */}
                <motion.circle
                  cx={p.x}
                  cy={p.y}
                  r={10}
                  fill="rgba(212,175,55,0.12)"
                  animate={{ r: [9, 13, 9], opacity: [0.5, 0.15, 0.5] }}
                  transition={{ duration: 2.4, repeat: Infinity, delay: i * 0.3 }}
                />

                {/* 节点圆心 */}
                <circle
                  cx={p.x}
                  cy={p.y}
                  r={4.5}
                  fill="#C9A961"
                  stroke="#FAF8F5"
                  strokeWidth="2"
                  style={{ filter: 'drop-shadow(0 0 4px rgba(201,169,97,0.4))' }}
                />

                {/* 城市标签 */}
                <text
                  x={p.x}
                  y={p.y - 13}
                  textAnchor="middle"
                  fontSize="11"
                  fill="#5C3A2E"
                  style={{ fontFamily: "'Noto Serif SC', serif", fontWeight: 500 }}
                >
                  {node.city}
                </text>
                <text
                  x={p.x}
                  y={p.y - 24}
                  textAnchor="middle"
                  fontSize="8.5"
                  fill="#B8973F"
                  style={{ fontFamily: "'Noto Serif SC', serif" }}
                >
                  {node.year} · {node.label}
                </text>
              </motion.g>
            );
          })}
        </svg>
      </motion.div>

      {/* 底部说明 */}
      <motion.p
        initial={{ opacity: 0 }}
        whileInView={{ opacity: 1 }}
        viewport={{ once: true }}
        transition={{ duration: 0.8, delay: 2.2 }}
        className="mt-3 text-center text-[10px] tracking-[0.2em] text-muted-foreground/70"
      >
        FROM FIRST MEETING TO FOREVER
      </motion.p>
    </div>
  );
}

export default memo(LoveMapTrail);
