import { memo, useState, useCallback, useRef, useEffect } from 'react';
import { motion } from 'framer-motion';
import { ArrowUp, Share2, Heart } from 'lucide-react';
import { NavLink } from '@lark-apaas/client-toolkit-lite';
import SectionWrapper from '@/components/SectionWrapper';
import FloralHeartDecor from '@/components/FloralHeartDecor';
import ShareGuide from '@/components/ShareGuide';
import PetalBurst from '@/components/PetalBurst';
import ShareEasterEgg from '@/components/ShareEasterEgg';
import AIBlessingGenerator from '@/components/AIBlessingGenerator';
import TimeCapsule from '@/components/TimeCapsule';
import InvitationPoster from '@/components/InvitationPoster';
import FoilText from '@/components/FoilText';
import { useLongPress } from '@/hooks/use-long-press';
import { MOCK_WEDDING_INFO } from '@/data/wedding';
import { SWEET_MESSAGES } from '@/lib/constants';

function EndingSection() {
  const [shareOpen, setShareOpen] = useState(false);
  const [burstTrigger, setBurstTrigger] = useState(false);
  const [sweetMsg, setSweetMsg] = useState<string | null>(null);
  const [eggTrigger, setEggTrigger] = useState(false);

  // 分享按钮快速点击计数
  const clickCountRef = useRef(0);
  const clickTimerRef = useRef<number | null>(null);

  const handleLongPress = useCallback(() => {
    const msg = SWEET_MESSAGES[Math.floor(Math.random() * SWEET_MESSAGES.length)];
    setSweetMsg(msg);
    setTimeout(() => setSweetMsg(null), 3500);
  }, []);

  const longPressProps = useLongPress(handleLongPress, 1500);

  // 监听摇一摇触发的分享事件
  useEffect(() => {
    const handleShareEvent = () => setShareOpen(true);
    window.addEventListener('wedding:share', handleShareEvent);
    return () => window.removeEventListener('wedding:share', handleShareEvent);
  }, []);

  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleShareClick = () => {
    // 快速点击计数：3秒内点5次触发彩蛋
    clickCountRef.current += 1;

    if (clickTimerRef.current) {
      clearTimeout(clickTimerRef.current);
    }

    // 达到5次且未触发过 → 触发彩蛋
    if (clickCountRef.current >= 5 && !eggTrigger) {
      setEggTrigger(true);
      clickCountRef.current = 0;
      // 5秒后重置彩蛋状态（允许再次触发）
      setTimeout(() => setEggTrigger(false), 5500);
      return;
    }

    // 正常点击 → 打开分享引导
    clickTimerRef.current = window.setTimeout(() => {
      setShareOpen(true);
      clickCountRef.current = 0;
    }, 400);
  };

  return (
    <>
      <ShareEasterEgg trigger={eggTrigger} />
      <PetalBurst trigger={burstTrigger} />

      <SectionWrapper
        id="ending"
        className="bg-gradient-to-b from-background via-primary/10 to-primary/20"
      >
        <motion.div
          initial={{ opacity: 0, scale: 0.8 }}
          whileInView={{ opacity: 1, scale: 1 }}
          viewport={{ once: true }}
          onViewportEnter={() => setBurstTrigger(true)}
          transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
        className="relative py-12 text-center md:py-16"
      >
        {/* 鲜花爱心装饰 */}
        <FloralHeartDecor className="absolute -left-2 top-0 z-0 h-24 w-24 opacity-70" variant="topLeft" />
        <FloralHeartDecor className="absolute -right-2 top-0 z-0 h-24 w-24 opacity-70" variant="topRight" />
        <FloralHeartDecor className="absolute -bottom-4 left-1/2 -translate-x-1/2 z-0 h-20 w-20 opacity-50" variant="heartOnly" />
          <motion.div
            initial={{ scale: 0 }}
            whileInView={{ scale: 1 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6, delay: 0.1, type: 'spring', stiffness: 200 }}
          >
            <Heart
              className="mx-auto h-10 w-10 fill-primary/20 text-primary"
              style={{ filter: 'drop-shadow(0 2px 8px rgba(212,175,55,0.2))' }}
            />
          </motion.div>

          <motion.h2
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.8, delay: 0.2 }}
            className="mt-6 text-3xl font-light tracking-wider md:text-4xl"
            style={{ fontFamily: "'Playfair Display', 'Noto Serif SC', serif" }}
          >
            <FoilText>期待您的到来</FoilText>
          </motion.h2>

          <motion.p
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.8, delay: 0.4 }}
            className="mt-2 text-sm italic text-muted-foreground"
            style={{ fontFamily: "'Great Vibes', 'Ma Shan Zheng', cursive" }}
          >
            Thank you for being part of our story
          </motion.p>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.8, delay: 0.5 }}
            className="mx-auto mt-8 flex items-center justify-center gap-3"
          >
            <div className="h-px w-10" style={{ background: 'linear-gradient(90deg, transparent, #C9A961)' }} />
            <span
              {...longPressProps}
              className="cursor-pointer select-none text-lg"
              style={{ fontFamily: "'Great Vibes', cursive", color: '#8B6B4A' }}
              title="长按查看甜蜜密语"
            >
              {MOCK_WEDDING_INFO.groomName} &amp; {MOCK_WEDDING_INFO.brideName}
            </span>
            <div className="h-px w-10" style={{ background: 'linear-gradient(90deg, #C9A961, transparent)' }} />
          </motion.div>

          {sweetMsg && (
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="mt-3"
            >
              <span
                className="inline-block rounded-full px-4 py-1.5 text-sm"
                style={{
                  background: 'rgba(255,255,240,0.9)',
                  backdropFilter: 'blur(8px)',
                  border: '1px solid rgba(212,175,55,0.25)',
                  fontFamily: "'Noto Serif SC', serif",
                  color: '#5C3A2E',
                }}
              >
                {sweetMsg}
              </span>
            </motion.div>
          )}

          <motion.p
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.8, delay: 0.6 }}
            className="mt-4 text-sm text-muted-foreground"
          >
            {MOCK_WEDDING_INFO.weddingDate} · {MOCK_WEDDING_INFO.weddingTime}
          </motion.p>
          <motion.p
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.8, delay: 0.7 }}
            className="mt-1 text-sm text-muted-foreground"
          >
            {MOCK_WEDDING_INFO.location}
          </motion.p>

          {/* AI 祝福生成器 */}
          <AIBlessingGenerator />

          {/* 时间胶囊 · 一周年之约 */}
          <TimeCapsule />

          {/* 专属请柬海报 */}
          <InvitationPoster />

          {/* 操作按钮 */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.8, delay: 0.8 }}
            className="mt-10 flex flex-col items-center gap-3"
          >
            <button
              onClick={handleShareClick}
              className="flex items-center gap-2 rounded-full border border-primary bg-transparent px-6 py-2.5 text-sm font-medium text-primary transition-all hover:bg-primary/10"
              style={{ boxShadow: '0 2px 12px rgba(212,175,55,0.1)' }}
            >
              <Share2 className="h-4 w-4" />
              分享给好友
            </button>

            {/* 彩蛋提示 */}
            {!eggTrigger && (
              <motion.p
                initial={{ opacity: 0 }}
                animate={{ opacity: 0.6 }}
                transition={{ delay: 0.5 }}
                className="text-[10px] tracking-wider"
                style={{
                  color: '#C9A961',
                  fontFamily: "'Noto Serif SC', serif",
                }}
              >
                ✦ 连点5次有惊喜哟 ✦
              </motion.p>
            )}

            <NavLink
              to="#hero"
              onClick={(e) => {
                e.preventDefault();
                scrollToTop();
              }}
              className="flex items-center gap-1.5 text-xs text-muted-foreground hover:text-primary"
            >
              <ArrowUp className="h-4 w-4" />
              回到顶部
            </NavLink>
          </motion.div>
        </motion.div>

        {/* 底部版权 */}
        <div className="border-t border-primary/10 pt-6 pb-2 text-center text-xs text-muted-foreground/70">
          <p>Made with <Heart className="inline h-3 w-3 fill-primary/50 text-primary/70" /> for our wedding</p>
          <p className="mt-1">© 2026 {MOCK_WEDDING_INFO.groomName} &amp; {MOCK_WEDDING_INFO.brideName}</p>
        </div>
      </SectionWrapper>

      <ShareGuide open={shareOpen} onClose={() => setShareOpen(false)} />
    </>
  );
}

export default memo(EndingSection);
