import { memo, useState, useRef, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import { Volume2, VolumeX } from 'lucide-react';
import SectionWrapper from '@/components/SectionWrapper';
import FloralHeartDecor from '@/components/FloralHeartDecor';

// 从 src/assets/video 目录导入视频
const videoModules = import.meta.glob(
  '@/assets/video/*.{mp4,webm,mov,MP4,WEBM,MOV}',
  { eager: true, query: '?url', import: 'default' }
) as Record<string, string>;

const VIDEO_URL =
  Object.entries(videoModules)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([, url]) => url)[0] || '';

function VideoSection({
  onSetMusicVolume,
}: {
  onSetMusicVolume?: (v: number) => void;
}) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isMuted, setIsMuted] = useState(true);
  const [showUnmuteHint, setShowUnmuteHint] = useState(false);
  // idle=未触发播放 loading=数据下载中 playing=正在播放
  const [videoState, setVideoState] = useState<'idle' | 'loading' | 'playing'>('idle');

  // 尝试播放（静音）：数据未就绪时等待 canplay 后自动重试，避免 preload=metadata
  // 下 play() 被浏览器拒绝导致"滚动到视频区不自动播放"
  const tryPlay = useCallback(() => {
    const v = videoRef.current;
    if (!v) return;
    v.muted = true;
    v.loop = true;
    const p = v.play();
    if (p !== undefined) {
      p.catch(() => {
        v.addEventListener(
          'canplay',
          () => {
            v.play().catch(() => {});
          },
          { once: true }
        );
      });
    }
  }, []);

  // 视频在页面加载时即预下载（preload=auto），滚动到视频区时已就绪可立即播放

  // 滚动进入视口前 500px 提前触发播放（静音）；离开视口暂停
  // 音量联动规则：仅当用户点击解除静音后才降低背景音乐；
  // 视频暂停（含滑出视口自动暂停）时恢复背景音乐音量
  useEffect(() => {
    if (!VIDEO_URL || !containerRef.current) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          const v = videoRef.current;
          if (!v) return;
          if (entry.isIntersecting) {
            tryPlay();
            setShowUnmuteHint(true);
            // 静音自动播放不干扰背景音乐：不调整音量，
            // 等待用户主动点击解除静音后再降低
          } else {
            v.pause();
            // 滑出视口：视频暂停，背景音乐恢复音量
            onSetMusicVolume?.(0.45);
            // 重置为静音态：再次滑入时需用户重新解除静音
            setIsMuted(true);
            setShowUnmuteHint(false);
          }
        });
      },
      { threshold: [0, 0.15, 0.3, 0.5] }
    );

    observer.observe(containerRef.current);
    return () => {
      observer.disconnect();
      // 组件卸载时恢复音量
      onSetMusicVolume?.(0.45);
    };
  }, [tryPlay, onSetMusicVolume]);

  // 视频任何暂停（手动或自动）：背景音乐恢复音量
  const handleVideoPause = useCallback(() => {
    onSetMusicVolume?.(0.45);
  }, [onSetMusicVolume]);

  // 视频结束时强制重新播放（兜底 loop 属性可能不生效的场景）
  const handleVideoEnded = () => {
    const v = videoRef.current;
    if (!v) return;
    v.currentTime = 0;
    v.play().catch(() => {});
  };

  const handleUnmute = () => {
    const v = videoRef.current;
    if (!v) return;
    v.muted = false;
    setIsMuted(false);
    setShowUnmuteHint(false);
    // 用户主动开启声音：保持背景音乐在低音量
    onSetMusicVolume?.(0.1);
  };

  return (
    <SectionWrapper
      id="video"
      className="bg-gradient-to-b from-background via-primary/5 to-background"
      delay={0.1}
    >
      {/* 标题 */}
      <div className="text-center">
        <p className="text-xs tracking-[0.3em] text-muted-foreground">VIDEO</p>
        <h2
          className="mt-2 text-2xl font-light tracking-wider md:text-3xl"
          style={{
            fontFamily: "'Playfair Display', 'Noto Serif SC', serif",
            background: 'linear-gradient(135deg, #C9A961 0%, #F4E4BC 50%, #C9A961 100%)',
            WebkitBackgroundClip: 'text',
            backgroundClip: 'text',
            WebkitTextFillColor: 'transparent',
          }}
        >
          幸福瞬间
        </h2>
        <div className="mx-auto mt-3 flex items-center justify-center gap-2">
          <span className="h-px w-12" style={{ background: 'linear-gradient(90deg, transparent, #C9A961, transparent)' }} />
          <span style={{ color: '#C9A961', fontSize: '10px' }}>✦</span>
          <span className="h-px w-12" style={{ background: 'linear-gradient(90deg, transparent, #C9A961, transparent)' }} />
        </div>
      </div>

      {/* 视频播放器 */}
      {VIDEO_URL ? (
        <div className="relative mt-8">
          {/* 鲜花爱心装饰 */}
          <FloralHeartDecor className="absolute -left-2 -top-2 z-10 h-20 w-20 md:h-24 md:w-24" variant="topLeft" />
          <FloralHeartDecor className="absolute -right-2 -top-2 z-10 h-20 w-20 md:h-24 md:w-24" variant="topRight" />
        <motion.div
          ref={containerRef}
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-40px' }}
          transition={{ duration: 0.6, delay: 0.15 }}
          className="relative overflow-hidden rounded-xl"
          style={{
            border: '1px solid rgba(212,175,55,0.25)',
            boxShadow: '0 8px 32px rgba(0,0,0,0.08), 0 2px 8px rgba(212,175,55,0.1)',
            background: 'rgba(255,255,240,0.6)',
            backdropFilter: 'blur(12px)',
            WebkitBackdropFilter: 'blur(12px)',
          }}
        >
          <div className="relative aspect-video w-full">
            <video
              ref={videoRef}
              src={VIDEO_URL}
              className="h-full w-full object-cover"
              playsInline
              // @ts-ignore
              webkit-playsinline="true"
              loop
              muted
              // 不设 autoPlay：由 IntersectionObserver 控制滑入视口时自动（静音）播放
              // preload=auto：进入页面即开始预下载视频，滑动到视频区时已就绪
              preload="auto"
              onEnded={handleVideoEnded}
              onPause={handleVideoPause}
              onClick={handleUnmute}
              onWaiting={() => setVideoState('loading')}
              onPlaying={() => setVideoState('playing')}
              onCanPlay={() => setVideoState('playing')}
              style={{ background: '#000' }}
            />

            {/* 视频数据下载中提示（进入视口触发播放后、首帧就绪前短暂出现） */}
            {videoState === 'loading' && (
              <div
                className="pointer-events-none absolute inset-0 z-10 flex items-center justify-center"
                style={{ background: 'rgba(16,20,27,0.55)' }}
              >
                <div
                  className="flex items-center gap-2 rounded-full px-4 py-2 text-xs"
                  style={{
                    background: 'rgba(255,255,240,0.92)',
                    backdropFilter: 'blur(8px)',
                    color: '#8B6B4A',
                    fontFamily: "'Noto Serif SC', serif",
                  }}
                >
                  <span className="h-2 w-2 animate-pulse rounded-full" style={{ background: '#C9A961' }} />
                  视频加载中…
                </div>
              </div>
            )}

            {/* 取消静音后右下角音量图标 */}
            {!isMuted && (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 0.8 }}
                className="absolute bottom-3 right-3 flex h-8 w-8 items-center justify-center rounded-full"
                style={{
                  background: 'rgba(0,0,0,0.4)',
                  backdropFilter: 'blur(4px)',
                }}
              >
                <Volume2 className="h-4 w-4" style={{ color: '#FAF8F5' }} />
              </motion.div>
            )}

            {/* 静音状态左上角小图标 */}
            {isMuted && (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 0.6 }}
                className="absolute left-3 top-3 flex h-7 w-7 items-center justify-center rounded-full"
                style={{
                  background: 'rgba(0,0,0,0.35)',
                  backdropFilter: 'blur(4px)',
                }}
              >
                <VolumeX className="h-3.5 w-3.5" style={{ color: '#FAF8F5' }} />
              </motion.div>
            )}
          </div>

          {/* 底部提示栏（在视频下方，小巧不遮挡） */}
          <div
            className="flex items-center justify-center gap-2 px-4 py-2.5"
            style={{
              borderTop: '1px solid rgba(212,175,55,0.12)',
              background: 'rgba(250,248,245,0.5)',
            }}
          >
            {isMuted ? (
              <button
                onClick={handleUnmute}
                className="flex items-center gap-1.5 text-xs transition-opacity hover:opacity-70"
                style={{
                  color: '#8B6B4A',
                  fontFamily: "'Noto Serif SC', serif",
                }}
              >
                <VolumeX className="h-3.5 w-3.5" style={{ color: '#C9A961' }} />
                点击视频开启声音
              </button>
            ) : (
              <span
                className="flex items-center gap-1.5 text-xs"
                style={{
                  color: '#8B6B4A',
                  fontFamily: "'Noto Serif SC', serif",
                }}
              >
                <Volume2 className="h-3.5 w-3.5" style={{ color: '#C9A961' }} />
                正在播放 · 见证我们的幸福时光
              </span>
            )}
          </div>
        </motion.div>
        </div>
      ) : (
        <motion.div
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="mt-8 flex flex-col items-center gap-3 py-16"
          style={{
            border: '1px dashed rgba(212,175,55,0.3)',
            borderRadius: '12px',
            background: 'rgba(250,248,245,0.4)',
            backdropFilter: 'blur(8px)',
            WebkitBackdropFilter: 'blur(8px)',
          }}
        >
          <span style={{ color: '#C9A961', fontSize: '24px' }}>✦</span>
          <p className="text-sm" style={{ color: '#8a7560', fontFamily: "'Noto Serif SC', serif" }}>
            视频准备中
          </p>
          <p className="text-xs text-muted-foreground/70">
            请将视频放入 src/assets/video/ 后重新构建
          </p>
        </motion.div>
      )}
    </SectionWrapper>
  );
}

export default memo(VideoSection);
