import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { BrowserRouter } from "react-router-dom";
import { ErrorBoundary } from "react-error-boundary";
import { AppContainer, ErrorRender } from "@lark-apaas/client-toolkit-lite";
import App from "./app";
import "./index.css";

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    {/* basename 跟随构建 base（import.meta.env.BASE_URL 构建时替换为字符串，不受
        CloudStudio 的 {{basename}} 模板变量影响）：
        - 根路径部署（CloudBase base=/）→ "/"
        - 子路径部署（GitHub Pages base=/wedding-invitation/）→ "/wedding-invitation/"
        由外层 Router 统一剥离，内层 Routes 不再设置 basename。 */}
    <BrowserRouter basename={import.meta.env.BASE_URL}>
      <AppContainer>
        <ErrorBoundary
          fallbackRender={({ error, resetErrorBoundary }) => (
            <ErrorRender error={error} resetErrorBoundary={resetErrorBoundary} />
          )}
        >
          <App />
        </ErrorBoundary>
      </AppContainer>
    </BrowserRouter>
  </StrictMode>,
);
