import { useEffect, useRef, memo } from 'react';

/**
 * 金色彩带（A1b 摇一摇彩带）
 * trigger 计数变化时，从顶部撒落金色彩带粒子（canvas 实现，2.6s 自动结束）
 */

interface GoldConfettiProps {
  /** 递增计数触发，0 表示未触发 */
  trigger: number;
}

interface Ribbon {
  x: number;
  y: number;
  vy: number;
  vx: number;
  len: number;
  rot: number;
  rotSpeed: number;
  swing: number;
  swingSpeed: number;
  color: string;
  opacity: number;
}

const GOLD_COLORS = [
  'rgba(212,175,55,0.9)',
  'rgba(201,169,97,0.85)',
  'rgba(244,228,188,0.9)',
  'rgba(232,196,196,0.75)',
  'rgba(212,165,165,0.7)',
];

function GoldConfetti({ trigger }: GoldConfettiProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const rafRef = useRef<number | null>(null);

  useEffect(() => {
    if (trigger <= 0) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

    const dpr = window.devicePixelRatio || 1;
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    canvas.style.width = `${window.innerWidth}px`;
    canvas.style.height = `${window.innerHeight}px`;
    ctx.scale(dpr, dpr);

    const W = window.innerWidth;
    const H = window.innerHeight;

    const ribbons: Ribbon[] = [];
    const count = 70;
    for (let i = 0; i < count; i++) {
      ribbons.push({
        x: Math.random() * W,
        y: -20 - Math.random() * H * 0.4,
        vy: 2.2 + Math.random() * 2.8,
        vx: -0.5 + Math.random(),
        len: 8 + Math.random() * 10,
        rot: Math.random() * Math.PI * 2,
        rotSpeed: -0.12 + Math.random() * 0.24,
        swing: Math.random() * Math.PI * 2,
        swingSpeed: 0.04 + Math.random() * 0.06,
        color: GOLD_COLORS[Math.floor(Math.random() * GOLD_COLORS.length)],
        opacity: 0.7 + Math.random() * 0.3,
      });
    }

    const start = performance.now();
    const DURATION = 2600;

    const loop = (now: number) => {
      const elapsed = now - start;
      // 最后 600ms 渐隐
      const fade = elapsed > DURATION - 600 ? Math.max(0, (DURATION - elapsed) / 600) : 1;

      ctx.clearRect(0, 0, W, H);

      for (const r of ribbons) {
        r.y += r.vy;
        r.swing += r.swingSpeed;
        r.x += r.vx + Math.sin(r.swing) * 0.8;
        r.rot += r.rotSpeed;

        ctx.save();
        ctx.translate(r.x, r.y);
        ctx.rotate(r.rot);
        ctx.globalAlpha = r.opacity * fade;
        ctx.fillStyle = r.color;

        // 彩带条（略弯）
        ctx.beginPath();
        ctx.ellipse(0, 0, r.len / 2.2, r.len, 0, 0, Math.PI * 2);
        ctx.fill();

        // 高光
        ctx.globalAlpha = r.opacity * fade * 0.4;
        ctx.fillStyle = '#FFFDF5';
        ctx.beginPath();
        ctx.ellipse(-r.len * 0.06, -r.len * 0.2, r.len / 7, r.len / 4, 0, 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();
      }

      if (elapsed < DURATION) {
        rafRef.current = requestAnimationFrame(loop);
      } else {
        ctx.clearRect(0, 0, W, H);
      }
    };

    rafRef.current = requestAnimationFrame(loop);

    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      ctx.clearRect(0, 0, W, H);
    };
  }, [trigger]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden="true"
      className="pointer-events-none fixed inset-0 z-[9990]"
    />
  );
}

export default memo(GoldConfetti);
