/**
 * 微信 JS-SDK 分享封装
 *
 * 用途：在微信内置浏览器中，通过 JS-SDK 精确控制「分享给朋友 / 分享到朋友圈」的
 * 标题、描述、封面图，替代对 OG 标签的不稳定抓取。
 *
 * 前置条件：
 * 1. 已认证的微信公众号（服务号/订阅号），在公众号后台「设置与开发 → 公众号设置 →
 *    功能设置 → JS 接口安全域名」中，把部署域名加入白名单。
 * 2. 后端提供签名接口（见 scripts/wx-sign-cloud-fn.js），返回 { appId, timestamp,
 *    nonceStr, signature }。
 *
 * 配置：在 src/lib/constants.ts 中设置 WX_APP_ID 与 WX_SIGN_API_URL。
 */

import { useEffect, useCallback, useRef } from 'react';
import { WX_APP_ID, WX_SIGN_API_URL, SHARE_TITLE, SHARE_DESCRIPTION, SHARE_IMAGE_URL } from '@/lib/constants';

// 微信 JS-SDK 全局类型声明
declare global {
  interface Window {
    wx?: {
      config: (cfg: Record<string, unknown>) => void;
      ready: (cb: () => void) => void;
      error: (cb: (err: unknown) => void) => void;
      updateAppMessageShareData: (data: Record<string, unknown>) => void;
      updateTimelineShareData: (data: Record<string, unknown>) => void;
      onMenuShareAppMessage?: (data: Record<string, unknown>) => void;
      onMenuShareTimeline?: (data: Record<string, unknown>) => void;
    };
  }
}

interface WxSignResult {
  appId: string;
  timestamp: number;
  nonceStr: string;
  signature: string;
}

/** 判断是否在微信内置浏览器中 */
export function isWeChat(): boolean {
  return /micromessenger/i.test(navigator.userAgent);
}

/** 动态加载微信 JS-SDK 脚本（仅加载一次） */
let sdkLoaded = false;
function loadWxSdk(): Promise<void> {
  return new Promise((resolve, reject) => {
    if (sdkLoaded && window.wx) {
      resolve();
      return;
    }
    if (document.getElementById('wx-jssdk')) {
      // 脚本已插入但可能未就绪，轮询等待
      const t = setInterval(() => {
        if (window.wx) {
          clearInterval(t);
          sdkLoaded = true;
          resolve();
        }
      }, 100);
      return;
    }
    const script = document.createElement('script');
    script.id = 'wx-jssdk';
    script.src = 'https://res.wx.qq.com/open/js/jweixin-1.6.0.js';
    script.async = true;
    script.onload = () => {
      sdkLoaded = true;
      resolve();
    };
    script.onerror = () => reject(new Error('微信 JS-SDK 加载失败'));
    document.head.appendChild(script);
  });
}

/** 从后端签名接口获取 wx.config 所需参数 */
async function fetchWxSign(apiUrl: string, pageUrl: string): Promise<WxSignResult> {
  const url = `${apiUrl}${apiUrl.includes('?') ? '&' : '?'}url=${encodeURIComponent(pageUrl)}`;
  const res = await fetch(url, { method: 'GET', credentials: 'omit' });
  if (!res.ok) throw new Error(`签名接口返回 ${res.status}`);
  return res.json();
}

/**
 * 微信分享 Hook
 * 在组件挂载时初始化 JS-SDK 并设置分享数据。
 * 非微信环境自动跳过（no-op）。
 */
export function useWechatShare() {
  const configuredRef = useRef(false);

  const setupShare = useCallback(async () => {
    // 非微信环境或未配置 AppID 时跳过
    if (!isWeChat() || !WX_APP_ID || !WX_SIGN_API_URL) return;
    if (configuredRef.current) return;

    try {
      await loadWxSdk();
      // 签名必须用当前页面完整 URL（去掉 hash），与 wx.config 所在页面一致
      const pageUrl = window.location.href.split('#')[0];
      const sign = await fetchWxSign(WX_SIGN_API_URL, pageUrl);

      window.wx?.config({
        debug: false, // 生产环境关闭 debug；调试时可临时置 true
        appId: sign.appId || WX_APP_ID,
        timestamp: sign.timestamp,
        nonceStr: sign.nonceStr,
        signature: sign.signature,
        jsApiList: [
          'updateAppMessageShareData',
          'updateTimelineShareData',
          'onMenuShareAppMessage',
          'onMenuShareTimeline',
        ],
        openTagList: [],
      });

      window.wx?.ready(() => {
        const shareData = {
          title: SHARE_TITLE,
          desc: SHARE_DESCRIPTION,
          link: window.location.href.split('#')[0],
          imgUrl: SHARE_IMAGE_URL,
          success: () => console.log('[wx-share] 分享成功'),
        };

        // 新版接口（推荐）
        window.wx?.updateAppMessageShareData?.(shareData);
        window.wx?.updateTimelineShareData?.(shareData);

        // 旧版接口兜底（部分安卓微信版本）
        window.wx?.onMenuShareAppMessage?.(shareData);
        window.wx?.onMenuShareTimeline?.(shareData);

        configuredRef.current = true;
      });

      window.wx?.error((err) => {
        console.warn('[wx-share] config 失败，回退到 OG 标签:', err);
      });
    } catch (err) {
      console.warn('[wx-share] 初始化失败，回退到 OG 标签:', err);
    }
  }, []);

  useEffect(() => {
    setupShare();
  }, [setupShare]);

  return { isWeChat: isWeChat() };
}