import { useEffect, useState } from 'react';

/**
 * 陀螺仪倾斜 hook（B2 烫金高光用）
 * 返回 -1 ~ 1 的归一化倾斜值（gamma 左右倾斜）
 * 无陀螺仪设备（桌面）→ 用缓慢正弦模拟流光，保证效果不缺失
 */
export function useTilt(): number {
  const [tilt, setTilt] = useState(0);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    let raf = 0;
    let gyroSeen = false;

    const handleOrientation = (e: DeviceOrientationEvent) => {
      if (e.gamma !== null && e.gamma !== undefined) {
        gyroSeen = true;
        const v = Math.max(-45, Math.min(45, e.gamma)) / 45; // -1 ~ 1
        setTilt(v);
      }
    };

    const fakeLoop = (t: number) => {
      // 6 秒一个周期的缓慢流光（仅无陀螺仪时）
      if (!gyroSeen) {
        setTilt(Math.sin((t / 1000) * (Math.PI / 3)) * 0.8);
        raf = requestAnimationFrame(fakeLoop);
      }
    };

    window.addEventListener('deviceorientation', handleOrientation, true);

    // 2 秒内没有陀螺仪数据 → 启动模拟流光
    const timer = window.setTimeout(() => {
      if (!gyroSeen) raf = requestAnimationFrame(fakeLoop);
    }, 2000);

    return () => {
      window.removeEventListener('deviceorientation', handleOrientation, true);
      window.clearTimeout(timer);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);

  return tilt;
}
