import { useEffect, useRef } from 'react';

/**
 * 摇一摇检测 hook
 * 检测设备摇动并触发回调（移动端专属）
 * 遵循 prefers-reduced-motion：开启时自动禁用
 */
export function useShakeDetection(onShake: () => void, threshold = 18) {
  const lastShakeRef = useRef(0);
  const callbackRef = useRef(onShake);

  useEffect(() => {
    callbackRef.current = onShake;
  }, [onShake]);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

    let lastX = 0, lastY = 0, lastZ = 0;
    let firstReading = true;

    const handle = (e: DeviceMotionEvent) => {
      const accel = e.accelerationIncludingGravity;
      if (!accel || accel.x == null || accel.y == null || accel.z == null) return;

      if (firstReading) {
        lastX = accel.x; lastY = accel.y; lastZ = accel.z;
        firstReading = false;
        return;
      }

      const dX = Math.abs(accel.x - lastX);
      const dY = Math.abs(accel.y - lastY);
      const dZ = Math.abs(accel.z - lastZ);
      lastX = accel.x; lastY = accel.y; lastZ = accel.z;

      if (dX + dY + dZ > threshold) {
        const now = Date.now();
        if (now - lastShakeRef.current > 2000) {
          lastShakeRef.current = now;
          callbackRef.current();
        }
      }
    };

    window.addEventListener('devicemotion', handle);
    return () => window.removeEventListener('devicemotion', handle);
  }, [threshold]);
}
