import { useEffect, useRef, memo } from 'react';

/**
 * 全局触摸爱心涟漪组件
 * 用户触摸屏幕任意位置时，从触点浮起金色爱心+涟漪扩散
 * 遵循 prefers-reduced-motion：开启时自动禁用
 */
function TouchHeartRipple() {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // 无障碍：减少动效偏好下直接跳过
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

    let lastSpawn = 0;
    const SPAWN_INTERVAL = 120;

    const spawnHeart = (x: number, y: number) => {
      const now = Date.now();
      if (now - lastSpawn < SPAWN_INTERVAL) return;
      lastSpawn = now;

      // 涟漪
      const ripple = document.createElement('div');
      ripple.style.cssText = `
        position: fixed; left: ${x}px; top: ${y}px;
        width: 4px; height: 4px; border-radius: 50%;
        border: 1.5px solid rgba(212,175,55,0.5);
        pointer-events: none; z-index: 9998;
        transform: translate(-50%,-50%);
        animation: heartRipple 0.7s ease-out forwards;
      `;
      container.appendChild(ripple);
      setTimeout(() => ripple.remove(), 700);

      // 爱心
      const heart = document.createElement('div');
      const offsetX = (Math.random() - 0.5) * 24;
      heart.style.cssText = `
        position: fixed; left: ${x + offsetX}px; top: ${y}px;
        pointer-events: none; z-index: 9999;
        animation: heartFloat 1.1s ease-out forwards;
      `;
      const size = 10 + Math.random() * 8;
      heart.innerHTML = `<svg viewBox="0 0 24 24" width="${size}" height="${size}">
        <path fill="rgba(212,175,55,0.75)" d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/>
      </svg>`;
      container.appendChild(heart);
      setTimeout(() => heart.remove(), 1100);
    };

    const handleTouch = (e: TouchEvent) => {
      if (e.touches.length > 0) {
        spawnHeart(e.touches[0].clientX, e.touches[0].clientY);
      }
    };

    const handleClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      // 按钮和链接不触发，避免干扰交互
      if (target.closest('button, a, input, textarea, select')) return;
      spawnHeart(e.clientX, e.clientY);
    };

    document.addEventListener('touchstart', handleTouch, { passive: true });
    document.addEventListener('click', handleClick, { passive: true });

    // 注入 keyframes
    const style = document.createElement('style');
    style.textContent = `
      @keyframes heartFloat {
        0% { transform: translateY(0) scale(0.4); opacity: 0; }
        15% { transform: translateY(-8px) scale(1); opacity: 0.85; }
        100% { transform: translateY(-70px) scale(0.5); opacity: 0; }
      }
      @keyframes heartRipple {
        0% { width: 4px; height: 4px; opacity: 0.6; }
        100% { width: 60px; height: 60px; opacity: 0; }
      }
    `;
    document.head.appendChild(style);

    return () => {
      document.removeEventListener('touchstart', handleTouch);
      document.removeEventListener('click', handleClick);
      style.remove();
    };
  }, []);

  return (
    <div
      ref={containerRef}
      className="pointer-events-none fixed inset-0 z-[9998]"
      aria-hidden="true"
    />
  );
}

export default memo(TouchHeartRipple);
