import { memo, useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { toast } from 'sonner';
import { MapPin, Clock, Calendar, Navigation, ExternalLink } from 'lucide-react';
import SectionWrapper from '@/components/SectionWrapper';
import FloralHeartDecor from '@/components/FloralHeartDecor';
import { MOCK_WEDDING_INFO } from '@/data/wedding';
import { openNav, type MapType } from '@/lib/map-navigation';

// 施家镇青杠嘴 坐标：纬度 30.318026, 经度 104.762858（WGS-84，腾讯地图精确值）
const MAP_LAT = 30.318026;
const MAP_LNG = 104.762858;
// 自建卫星地图页（public/map-embed.html）：
// Leaflet + 高德卫星瓦片（免 key 国内直连），替代被墙的 Google Maps / OSM+ESRI
// 相对路径引用，与部署目录位置无关
const MAP_EMBED_URL = 'map-embed.html';

function WeddingInfoSection() {
  const [showMapOptions, setShowMapOptions] = useState(false);
  const [mapLoaded, setMapLoaded] = useState(false);
  const [mapFailed, setMapFailed] = useState(false);

  // 6s 兜底：仍未加载完成则显示静态提示
  useEffect(() => {
    const t = setTimeout(() => {
      if (!mapLoaded) setMapFailed(true);
    }, 6000);
    return () => clearTimeout(t);
  }, [mapLoaded]);

  const handleNav = (type: MapType) => {
    openNav(type, {
      address: MOCK_WEDDING_INFO.address,
      lat: MAP_LAT,
      lng: MAP_LNG,
      name: '施家镇青杠嘴',
    });
    setShowMapOptions(false);
    toast.success('正在打开地图导航');
  };

  const timeCards = [
    { label: '迎宾签到', time: MOCK_WEDDING_INFO.signInTime, icon: Clock },
    { label: '婚礼仪式', time: MOCK_WEDDING_INFO.ceremonyTime, icon: Calendar },
    { label: '喜宴开席', time: MOCK_WEDDING_INFO.banquetTime, icon: MapPin },
  ];

  return (
    <SectionWrapper id="info">
      <div className="text-center">
        <p className="text-xs tracking-[0.3em] text-muted-foreground">WEDDING INFO</p>
        <h2
          className="mt-2 text-2xl font-light tracking-wider md:text-3xl"
          style={{
            fontFamily: "'Playfair Display', 'Noto Serif SC', serif",
            background: 'linear-gradient(135deg, #C9A961 0%, #F4E4BC 50%, #C9A961 100%)',
            WebkitBackgroundClip: 'text',
            backgroundClip: 'text',
            WebkitTextFillColor: 'transparent',
          }}
        >
          婚礼信息
        </h2>
      </div>

      {/* 时间卡片 */}
      <div className="mt-10 grid grid-cols-3 gap-3">
        {timeCards.map((card, idx) => {
          const Icon = card.icon;
          return (
            <motion.div
              key={card.label}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: idx * 0.1 }}
              className="flex flex-col items-center gap-2 rounded-lg p-4 text-center"
              style={{
                background: 'rgba(255,255,255,0.5)',
                backdropFilter: 'blur(12px)',
                WebkitBackdropFilter: 'blur(12px)',
                border: '1px solid rgba(212,175,55,0.2)',
                boxShadow: '0 4px 16px rgba(212,175,55,0.06)',
              }}
            >
              <Icon className="h-5 w-5 text-primary" />
              <p className="text-xs text-muted-foreground">{card.label}</p>
              <p
                className="text-lg font-semibold text-primary md:text-xl"
                style={{ fontFamily: "'Playfair Display', serif" }}
              >
                {card.time}
              </p>
            </motion.div>
          );
        })}
      </div>

      {/* 详细地址 */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true }}
        transition={{ duration: 0.6, delay: 0.2 }}
        className="relative mt-8 overflow-hidden rounded-xl p-5"
        style={{
          background: 'rgba(255,255,255,0.5)',
          backdropFilter: 'blur(12px)',
          WebkitBackdropFilter: 'blur(12px)',
          border: '1px solid rgba(212,175,55,0.2)',
          boxShadow: '0 4px 16px rgba(212,175,55,0.06)',
        }}
      >
        <div className="flex items-start gap-3">
          <MapPin className="mt-0.5 h-5 w-5 shrink-0 text-primary" />
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium text-foreground">婚礼地点</p>
            <p className="mt-1 text-sm leading-relaxed text-muted-foreground">
              {MOCK_WEDDING_INFO.location}
            </p>
          </div>
        </div>

        <div className="mt-4 flex items-start gap-3">
          <Calendar className="mt-0.5 h-5 w-5 shrink-0 text-primary" />
          <div className="flex-1">
            <p className="text-sm font-medium text-foreground">婚礼日期</p>
            <p className="mt-1 text-sm text-muted-foreground">
              {MOCK_WEDDING_INFO.weddingDate} · {MOCK_WEDDING_INFO.lunarDate}
            </p>
          </div>
        </div>

        {/* 鲜花装饰 */}
        <FloralHeartDecor className="absolute -right-1 -top-1 z-10 h-16 w-16 opacity-80" variant="topRight" />

        {/* 卫星地图嵌入（OpenStreetMap + ESRI 卫星瓦片） */}
        <div className="relative mt-5 overflow-hidden rounded-lg" style={{ border: '1px solid rgba(212,175,55,0.3)' }}>
          {!mapFailed ? (
            <>
              <iframe
                src={MAP_EMBED_URL}
                title="婚礼场地卫星地图"
                className="block w-full"
                style={{ height: '200px', border: 0 }}
                loading="lazy"
                referrerPolicy="no-referrer-when-downgrade"
                onLoad={() => setMapLoaded(true)}
                onError={() => setMapFailed(true)}
              />
              {!mapLoaded && (
                <div
                  className="pointer-events-none absolute inset-0 flex items-center justify-center"
                  style={{
                    background: 'linear-gradient(135deg, rgba(212,175,55,0.08), rgba(212,165,165,0.08))',
                  }}
                >
                  <div className="flex items-center gap-2 text-xs" style={{ color: '#8B6B4A' }}>
                    <span className="h-2 w-2 animate-pulse rounded-full" style={{ background: '#C9A961' }} />
                    正在加载卫星地图…
                  </div>
                </div>
              )}
            </>
          ) : (
            // 加载失败兜底：纯文字卡片 + 坐标 + 一键导航提示
            <div
              className="flex flex-col items-center justify-center gap-2 px-4 py-10"
              style={{
                background: 'linear-gradient(135deg, rgba(212,175,55,0.06), rgba(212,165,165,0.06))',
                height: '200px',
              }}
            >
              <MapPin className="h-7 w-7" style={{ color: '#C9A961' }} />
              <p
                className="text-sm font-medium"
                style={{
                  fontFamily: "'Noto Serif SC', serif",
                  color: '#5C3A2E',
                }}
              >
                卫星地图加载失败
              </p>
              <p
                className="text-xs"
                style={{
                  color: '#8B6B4A',
                  fontFamily: "'Noto Serif SC', serif",
                }}
              >
                经度 {MAP_LNG.toFixed(4)} · 纬度 {MAP_LAT.toFixed(4)}
              </p>
              <p className="text-xs" style={{ color: '#A89070' }}>
                请点击下方"一键导航"跳转地图 App
              </p>
            </div>
          )}

          {/* 地址标签覆盖 */}
          <div
            className="pointer-events-none absolute bottom-2 left-2 rounded-full px-3 py-1 text-xs"
            style={{
              background: 'rgba(255,255,240,0.85)',
              backdropFilter: 'blur(8px)',
              color: '#8B6B4A',
              fontFamily: "'Noto Serif SC', serif",
            }}
          >
            📍 {MOCK_WEDDING_INFO.location}
          </div>
        </div>

        {/* 一键导航按钮 */}
        <div className="relative mt-5">
          <button
            onClick={() => setShowMapOptions(!showMapOptions)}
            className="flex w-full items-center justify-center gap-2 rounded-full border border-primary bg-transparent py-3 text-sm font-medium text-primary transition-all hover:bg-primary/10"
          >
            <Navigation className="h-4 w-4" />
            一键导航
          </button>

          {showMapOptions && (
            <motion.div
              initial={{ opacity: 0, y: -8 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -8 }}
              className="absolute bottom-full left-0 right-0 mb-2 overflow-hidden rounded-lg border border-primary/30 bg-card shadow-lg"
            >
              <button
                onClick={() => handleNav('amap')}
                className="flex w-full items-center gap-2 px-4 py-3 text-left text-sm hover:bg-muted"
              >
                <span className="text-base">🗺️</span>
                <div className="flex-1">
                  <div>高德地图导航</div>
                  <div className="text-[10px] text-muted-foreground">传坐标精准定位</div>
                </div>
                <ExternalLink className="h-3 w-3 text-muted-foreground" />
              </button>
              <div className="h-px bg-border" />
              <button
                onClick={() => handleNav('bmap')}
                className="flex w-full items-center gap-2 px-4 py-3 text-left text-sm hover:bg-muted"
              >
                <span className="text-base">🗺️</span>
                <div className="flex-1">
                  <div>百度地图导航</div>
                  <div className="text-[10px] text-muted-foreground">自动转换坐标系</div>
                </div>
                <ExternalLink className="h-3 w-3 text-muted-foreground" />
              </button>
              <div className="h-px bg-border" />
              <button
                onClick={() => handleNav('tencent')}
                className="flex w-full items-center gap-2 px-4 py-3 text-left text-sm hover:bg-muted"
              >
                <span className="text-base">🗺️</span>
                <div className="flex-1">
                  <div>腾讯地图导航</div>
                  <div className="text-[10px] text-muted-foreground">原生唤起</div>
                </div>
                <ExternalLink className="h-3 w-3 text-muted-foreground" />
              </button>
              <div className="h-px bg-border" />
              <button
                onClick={() => handleNav('system')}
                className="flex w-full items-center gap-2 px-4 py-3 text-left text-sm hover:bg-muted"
              >
                <span className="text-base">📍</span>
                <div className="flex-1">
                  <div>系统地图导航</div>
                  <div className="text-[10px] text-muted-foreground">iOS 用 Apple Maps</div>
                </div>
                <ExternalLink className="h-3 w-3 text-muted-foreground" />
              </button>
            </motion.div>
          )}
        </div>
      </motion.div>
    </SectionWrapper>
  );
}

export default memo(WeddingInfoSection);
